/**
 * Deterministischer Zufallsgenerator.
 *
 * Kombiniert xmur3 (Seed -> 32-Bit-Startwert) mit mulberry32 (PRNG).
 * Dadurch ist jedes Rätsel über seinen Seed exakt reproduzierbar –
 * Grundlage für "Seed teilen" und für die Tests.
 */

/** Erzeugt eine 32-Bit-Seedfunktion aus einem beliebigen String. */
export function hashSeed(str) {
  let h = 1779033703 ^ String(str).length;
  for (let i = 0; i < String(str).length; i++) {
    h = Math.imul(h ^ String(str).charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return function () {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    h ^= h >>> 16;
    return h >>> 0;
  };
}

/** Schneller, gleichverteilter 32-Bit-PRNG. Gibt Float in [0, 1). */
export function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class RNG {
  constructor(seed = 'hashi') {
    this.seed = String(seed);
    this._next = mulberry32(hashSeed(this.seed)());
  }

  /** Zufallszahl in [0, 1). */
  float() {
    return this._next();
  }

  /** Ganzzahl in [0, maxExclusive). */
  int(maxExclusive) {
    return Math.floor(this._next() * maxExclusive);
  }

  /** Ganzzahl in [min, max] (einschließlich). */
  range(min, max) {
    return min + this.int(max - min + 1);
  }

  /** Zufälliges Element aus einem Array. */
  pick(arr) {
    return arr[this.int(arr.length)];
  }

  /** Wahrheitswert mit Wahrscheinlichkeit p. */
  chance(p) {
    return this._next() < p;
  }

  /** Fisher-Yates-Shuffle (in place). */
  shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = this.int(i + 1);
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  /** Gewichtete Zufallsauswahl. `weights` hat dieselbe Länge wie `items`. */
  pickWeighted(items, weights) {
    let total = 0;
    for (const w of weights) total += w;
    if (total <= 0) return this.pick(items);
    let r = this._next() * total;
    for (let i = 0; i < items.length; i++) {
      r -= weights[i];
      if (r <= 0) return items[i];
    }
    return items[items.length - 1];
  }
}

/** Erzeugt einen lesbaren, zufälligen Seed (z. B. "K4F-92QX"). */
export function randomSeed() {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const bytes = new Uint8Array(8);
  if (typeof globalThis.crypto?.getRandomValues === 'function') {
    globalThis.crypto.getRandomValues(bytes);
  } else {
    for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256);
  }
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    out += alphabet[bytes[i] % alphabet.length];
    if (i % 4 === 3 && i !== bytes.length - 1) out += '-';
  }
  return out;
}

/**
 * Spielbrett-Modell für Hashiwokakero.
 *
 * Enthält die komplette Spiellogik, die unabhängig von der Oberfläche ist:
 *  - Kanten (mögliche Brücken) zwischen benachbarten Inseln
 *  - Kreuzungen (dürfen sich nicht kreuzen)
 *  - Nachbarschafts-Listen
 *
 * Regeln, die das Modell abbildet:
 *  1. Eine Brücke verbindet genau zwei Inseln auf derselben Zeile/Spalte,
 *     zwischen denen keine weitere Insel liegt.
 *  2. Zwischen zwei Inseln sind maximal 2 Brücken erlaubt.
 *  3. Brücken dürfen sich nicht kreuzen.
 *  4. Jede Insel trägt so viele Brücken, wie ihre Zahl angibt.
 *  5. Alle Inseln müssen am Ende über Brücken verbunden sein.
 */

/**
 * @typedef {Object} Island
 * @property {number} id     Eindeutige Insel-ID (Index im Brett)
 * @property {number} r      Zeile
 * @property {number} c      Spalte
 * @property {number} num    Erforderliche Anzahl Brücken
 */

/**
 * @typedef {Object} Edge
 * @property {string} id     Eindeutige Kanten-ID
 * @property {number} a      Insel-Index A
 * @property {number} b      Insel-Index B
 * @property {'h'|'v'} dir   Orientierung
 * @property {number} r1     Zeile Start
 * @property {number} c1     Spalte Start
 * @property {number} r2     Zeile Ende
 * @property {number} c2     Spalte Ende
 */

/**
 * Prüft, ob sich zwei Kanten kreuzen würden.
 * Nur horizontale/vertikale Paare können sich kreuzen.
 */
export function edgesCross(e, f) {
  if (e.dir === f.dir) return false;
  const h = e.dir === 'h' ? e : f;
  const v = e.dir === 'h' ? f : e;
  return h.c1 < v.c1 && v.c1 < h.c2 && v.r1 < h.r1 && h.r1 < v.r2;
}

/**
 * Baut das vollständige Brettmodell.
 *
 * @param {Island[]} islands  Inseln mit Nummer
 * @param {number} cols       Spaltenzahl des Gitters
 * @param {number} rows       Zeilenzahl des Gitters
 */
export function buildBoard(islands, cols, rows) {
  const list = islands.map((s, i) => ({
    id: s.id ?? i,
    index: i,
    r: s.r,
    c: s.c,
    num: s.num,
  }));

  const edges = [];

  // Horizontale Kanten: aufeinanderfolgende Inseln einer Zeile.
  const byRow = new Map();
  for (const isl of list) {
    if (!byRow.has(isl.r)) byRow.set(isl.r, []);
    byRow.get(isl.r).push(isl);
  }
  for (const r of [...byRow.keys()].sort((a, b) => a - b)) {
    const arr = byRow.get(r).sort((a, b) => a.c - b.c);
    for (let i = 0; i + 1 < arr.length; i++) {
      const a = arr[i];
      const b = arr[i +1];
      edges.push({
        id: `e${edges.length}`,
        a: a.index,
        b: b.index,
        dir: 'h',
        r1: a.r,
        c1: a.c,
        r2: b.r,
        c2: b.c,
      });
    }
  }

  // Vertikale Kanten: aufeinanderfolgende Inseln einer Spalte.
  const byCol = new Map();
  for (const isl of list) {
    if (!byCol.has(isl.c)) byCol.set(isl.c, []);
    byCol.get(isl.c).push(isl);
  }
  for (const c of [...byCol.keys()].sort((a, b) => a - b)) {
    const arr = byCol.get(c).sort((a, b) => a.r - b.r);
    for (let i = 0; i + 1 < arr.length; i++) {
      const a = arr[i];
      const b = arr[i + 1];
      edges.push({
        id: `e${edges.length}`,
        a: a.index,
        b: b.index,
        dir: 'v',
        r1: a.r,
        c1: a.c,
        r2: b.r,
        c2: b.c,
      });
    }
  }

  // Kreuzungen
  const crossings = edges.map(() => []);
  for (let i = 0; i < edges.length; i++) {
    for (let j = i + 1; j < edges.length; j++) {
      if (edgesCross(edges[i], edges[j])) {
        crossings[i].push(j);
        crossings[j].push(i);
      }
    }
  }

  // Inzidenz: pro Insel die Liste der Kanten-Indizes
  const incident = list.map(() => []);
  edges.forEach((e, i) => {
    incident[e.a].push(i);
    incident[e.b].push(i);
  });

  // Nachbarschaft: pro Insel die Nachbarn (über eine Kante erreichbar)
  const neighbors = list.map(() => []);
  edges.forEach((e, i) => {
    neighbors[e.a].push({ edge: i, other: e.b });
    neighbors[e.b].push({ edge: i, other: e.a });
  });

  return { cols, rows, islands: list, edges, crossings, incident, neighbors };
}

/**
 * Prüft, ob ein Zellenpunkt von einer Insel belegt ist.
 */
export function findIslandAt(islands, r, c) {
  return islands.find((i) => i.r === r && i.c === c) ?? null;
}

/**
 * Prüft, ob alle Inseln über die gesetzten Brücken verbunden sind.
 *
 * @param {number[]} counts  Anzahl Brücken pro Kante (Index = Kanten-Index)
 */
export function isConnected(board, counts) {
  const n = board.islands.length;
  if (n === 0) return true;
  const parent = new Int32Array(n);
  for (let i = 0; i < n; i++) parent[i] = i;
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  };
  board.edges.forEach((e, i) => {
    if ((counts[i] ?? 0) > 0) union(e.a, e.b);
  });
  const root = find(0);
  for (let i = 1; i < n; i++) {
    if (find(i) !== root) return false;
  }
  return true;
}

/**
 * Constraint-basierter Solver für Hashiwokakero.
 *
 * Der Solver arbeitet mit Domänen (Bitmasken) pro Kante:
 *   Bit 0 -> Brückenzahl 0 erlaubt
 *   Bit 1 -> Brückenzahl 1 erlaubt
 *   Bit 2 -> Brückenzahl 2 erlaubt
 *
 * Propagationsregeln:
 *   A) Insel-Summe:  sum(Brücken an Insel i) == Zahl(i)
 *      -> Vor dem Verzweigen wird jede Kante auf den Bereich
 *         [zahl - max(Rest), zahl - min(Rest)] eingeschränkt.
 *   B) Kreuzungen:    zwei sich kreuzende Kanten dürfen nicht beide > 0 sein.
 *      -> Ist eine Kante auf > 0 festgelegt, werden alle Kreuzungen auf 0.
 *   C) Konnektivität: alle Inseln müssen am Ende erreichbar sein.
 *      -> Der "potentielle" Graph (Kanten, die > 0 sein *könnten*) muss
 *         connected sein, sonst kann es keine Lösung geben.
 *
 * Rückgabe: Liste der gefundenen Lösungen (abgebrochen nach `limit`).
 * Damit lässt sich Eindeutigkeit prüfen: 1 Lösung = eindeutig lösbar.
 */

const D0 = 1;
const D1 = 2;
const D2 = 4;
const DOM_ALL = D0 | D1 | D2;

const minVal = (d) => (d & D0 ? 0 : d & D1 ? 1 : 2);
const maxVal = (d) => (d & D2 ? 2 : d & D1 ? 1 : 0);
const valOf = (d) => (d & D2 ? 2 : d & D1 ? 1 : 0);
const popcount = (d) => (d & D0 ? 1 : 0) + (d & D1 ? 1 : 0) + (d & D2 ? 1 : 0);

export class Solver {
  /** @param {ReturnType<import('./board.js').buildBoard>} board */
  constructor(board) {
    this.board = board;
    this.edges = board.edges;
    this.m = board.edges.length;
    this.incident = board.incident;
    this.crossings = board.crossings;
    this.islands = board.islands;
    this.nodes = 0; // Anzahl der Suchknoten (Statistik)
  }

  /**
   * Sucht bis zu `limit` Lösungen.
   * @param {number} limit
   * @returns {number[][]} Array von Brückenzahlen pro Kante
   */
  findSolutions(limit = 2) {
    const { edges, m, incident, crossings, islands } = this;
    const solutions = [];
    this.nodes = 0;

    if (islands.length === 0) return solutions;

    // Erreichbarkeit über "mögliche" Kanten (potentieller Graph)
    const potentialConnected = (d) => {
      const n = islands.length;
      const parent = new Int32Array(n);
      for (let i = 0; i < n; i++) parent[i] = i;
      const find = (x) => {
        while (parent[x] !== x) {
          parent[x] = parent[parent[x]];
          x = parent[x];
        }
        return x;
      };
      for (let e = 0; e < m; e++) {
        if (d[e] & (D1 | D2)) {
          const ra = find(edges[e].a);
          const rb = find(edges[e].b);
          if (ra !== rb) parent[ra] = rb;
        }
      }
      const root = find(0);
      for (let i = 1; i < n; i++) if (find(i) !== root) return false;
      return true;
    };

    const isCompleteSolution = (counts) => {
      // Insel-Summen exakt? (Propagation garantiert das, aber wir prüfen sicherheitshalber)
      for (let i = 0; i < islands.length; i++) {
        let sum = 0;
        for (const e of incident[i]) sum += counts[e];
        if (sum !== islands[i].num) return false;
      }
      // Kreuzungen?
      for (let e = 0; e < m; e++) {
        if (counts[e] === 0) continue;
        for (const f of crossings[e]) {
          if (counts[f] > 0) return false;
        }
      }
      // Verbunden?
      const n = islands.length;
      const seen = new Uint8Array(n);
      const stack = [0];
      seen[0] = 1;
      let reached = 1;
      while (stack.length) {
        const cur = stack.pop();
        for (const e of incident[cur]) {
          if (counts[e] === 0) continue;
          const other = edges[e].a === cur ? edges[e].b : edges[e].a;
          if (!seen[other]) {
            seen[other] = 1;
            reached++;
            stack.push(other);
          }
        }
      }
      return reached === n;
    };

    const propagate = (d) => {
      let changed = true;
      while (changed) {
        changed = false;

        // (A) Insel-Summen
        for (let i = 0; i < islands.length; i++) {
          const t = islands[i].num;
          const es = incident[i];
          if (es.length === 0) {
            if (t !== 0) return false;
            continue;
          }
          let minS = 0;
          let maxS = 0;
          for (const e of es) {
            minS += minVal(d[e]);
            maxS += maxVal(d[e]);
          }
          if (minS > t || maxS < t) return false;

          for (const e of es) {
            const othersMin = minS - minVal(d[e]);
            const othersMax = maxS - maxVal(d[e]);
            const lo = t - othersMax;
            const hi = t - othersMin;
            const cur = d[e];
            let nd = 0;
            if (cur & D0 && 0 >= lo && 0 <= hi) nd |= D0;
            if (cur & D1 && 1 >= lo && 1 <= hi) nd |= D1;
            if (cur & D2 && 2 >= lo && 2 <= hi) nd |= D2;
            if (nd === 0) return false;
            if (nd !== cur) {
              d[e] = nd;
              changed = true;
            }
          }
        }

        // (B) Kreuzungen
        for (let e = 0; e < m; e++) {
          if (d[e] & D0) continue; // 0 ist noch möglich -> kein Zwang
          for (const f of crossings[e]) {
            if (d[f] & (D1 | D2)) {
              if (!(d[f] & D0)) return false; // beide >0 erzwungen -> Konflikt
              d[f] = D0;
              changed = true;
            }
          }
        }
      }
      return true;
    };

    const search = (d) => {
      if (solutions.length >= limit) return;
      this.nodes++;

      // Verzweigung: Kante mit der kleinsten Domäne wählen
      let best = -1;
      let bestScore = Infinity;
      for (let e = 0; e < m; e++) {
        const size = popcount(d[e]);
        if (size <= 1) continue;
        const score = size * 1000 + crossings[e].length;
        if (score < bestScore) {
          bestScore = score;
          best = e;
        }
      }

      if (best === -1) {
        // Alle Kanten sind festgelegt -> Kandidat prüfen
        const counts = new Int8Array(m);
        for (let e = 0; e < m; e++) counts[e] = valOf(d[e]);
        if (isCompleteSolution(counts)) solutions.push(Array.from(counts));
        return;
      }

      const cur = d[best];
      // Reihenfolge: erst "viele" Brücken, dann mittlere, dann keine.
      // Findet schneller eine (beliebige) Lösung.
      for (const v of [2, 1, 0]) {
        if (!(cur & (1 << v))) continue;
        const nd = Int8Array.from(d);
        nd[best] = 1 << v;
        if (propagate(nd) && potentialConnected(nd)) search(nd);
        if (solutions.length >= limit) return;
      }
    };

    const dom = new Int8Array(m).fill(DOM_ALL);
    if (!propagate(dom)) return solutions;
    if (!potentialConnected(dom)) return solutions;
    search(dom);
    return solutions;
  }

  /**
   * Bequemlichkeit: prüft, ob das Brett genau eine Lösung besitzt.
   */
  hasUniqueSolution() {
    return this.findSolutions(2).length === 1;
  }
}

/**
 * @param {ReturnType<import('./board.js').buildBoard>} board
 * @param {number} limit
 */
export function findSolutions(board, limit = 2) {
  return new Solver(board).findSolutions(limit);
}

/**
 * Prüft, ob ein Brett eindeutig lösbar ist, und liefert die Lösung zurück.
 * @returns {{ unique: boolean, solution: number[]|null, count: number }}
 */
export function analyzeBoard(board) {
  const solutions = findSolutions(board, 3);
  return {
    unique: solutions.length === 1,
    solution: solutions[0] ?? null,
    count: solutions.length,
  };
}

