/**
 * Rätselgenerator für Hashiwokakero.
 *
 * Pipeline:
 *   1. `growSolution` erzeugt per Zufall eine *gültige Lösung*:
 *      Inseln wachsen zu einem Baum, Brücken verbinden sie kreuzungsfrei.
 *      Aus den Brücken ergeben sich die Inselzahlen.
 *   2. Der Solver prüft, ob das Rätsel eindeutig lösbar ist.
 *   3. `repair` mutiert die Lösung, bis Eindeutigkeit erreicht ist
 *      (mutationsbasiertes Hill-Climbing, Ziel: 1 Lösung).
 *   4. Aus mehreren eindeutigen Kandidaten wird der "interessanteste" gewählt.
 *
 * Erzeugte Rätsel erfüllen immer:
 *   - alle Inseln liegen auf verschiedenen Feldern
 *   - keine Brücke kreuzt eine andere, keine Brücke liegt über einer Insel
 *   - jede Insel trägt 1..8 Brücken
 *   - es existiert genau eine Lösung
 *   - alle Inseln sind in dieser Lösung verbunden
 */

import { RNG, randomSeed } from './rng.js';
import { buildBoard, isConnected } from './board.js';
import { findSolutions } from './solver.js';

export const DIFFICULTIES = {
  easy: {
    id: 'easy',
    label: 'Leicht',
    min: 7,
    max: 11,
    cols: 8,
    rows: 8,
    double: 0.2,
    tries: 80,
    maxRepair: 120,
    keep: 5,
  },
  medium: {
    id: 'medium',
    label: 'Mittel',
    min: 11,
    max: 16,
    cols: 9,
    rows: 9,
    double: 0.3,
    tries: 80,
    maxRepair: 160,
    keep: 5,
  },
  hard: {
    id: 'hard',
    label: 'Schwer',
    min: 16,
    max: 22,
    cols: 10,
    rows: 10,
    double: 0.38,
    tries: 80,
    maxRepair: 200,
    keep: 4,
  },
  expert: {
    id: 'expert',
    label: 'Experte',
    min: 22,
    max: 30,
    cols: 12,
    rows: 12,
    double: 0.44,
    tries: 80,
    maxRepair: 240,
    keep: 3,
  },
};

export const DIFFICULTY_IDS = Object.keys(DIFFICULTIES);

const DIRS = [
  { dr: -1, dc: 0, dir: 'v' },
  { dr: 1, dc: 0, dir: 'v' },
  { dr: 0, dc: -1, dir: 'h' },
  { dr: 0, dc: 1, dir: 'h' },
];

const key = (r, c) => `${r},${c}`;
const edgeKey = (a, b) => (a < b ? `${a}-${b}` : `${b}-${a}`);
const sameArray = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);

/* ------------------------------------------------------------------ *
 * Schritt 1: Zufällige Lösung wachsen lassen
 * ------------------------------------------------------------------ */

/** Ist die Zelle (r,c) von einer Insel belegt? */
function islandAt(islands, r, c) {
  return islands.some((i) => i.r === r && i.c === c);
}

/**
 * Anzahl sichtbarer Nachbarn einer Zelle: für jede Richtung der nächste
 * Insel-Punkt ohne dazwischenliegende Insel. Bestimmt, wie viele
 * potenzielle Brückenkanten an der Zelle entstehen.
 */
function visibleDegree(islands, r, c, rows, cols) {
  let deg = 0;
  for (const d of DIRS) {
    let step = 1;
    while (true) {
      const nr = r + d.dr * step;
      const nc = c + d.dc * step;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) break;
      if (islandAt(islands, nr, nc)) {
        deg++;
        break;
      }
      step++;
    }
  }
  return deg;
}

/** Liegt die Zelle (r,c) im Inneren einer bestehenden Brücke? */
function liesOnBridge(edges, r, c) {
  for (const e of edges) {
    if (e.a.r === e.b.r) {
      if (e.a.r === r && Math.min(e.a.c, e.b.c) < c && c < Math.max(e.a.c, e.b.c)) return true;
    } else if (e.a.c === e.b.c) {
      if (e.a.c === c && Math.min(e.a.r, e.b.r) < r && r < Math.max(e.a.r, e.b.r)) return true;
    }
  }
  return false;
}

/** Würde die Strecke (r1,c1)->(r2,c2) eine bestehende Brücke kreuzen? */
function crossesExisting(edges, r1, c1, r2, c2) {
  const horizontal = r1 === r2;
  for (const e of edges) {
    const eHorizontal = e.a.r === e.b.r;
    if (eHorizontal === horizontal) continue; // parallel -> kein Kreuz
    if (horizontal) {
      const ec = e.a.c;
      const er1 = Math.min(e.a.r, e.b.r);
      const er2 = Math.max(e.a.r, e.b.r);
      if (er1 < r1 && r1 < er2 && Math.min(c1, c2) < ec && ec < Math.max(c1, c2)) return true;
    } else {
      const er = e.a.r;
      const ec1 = Math.min(e.a.c, e.b.c);
      const ec2 = Math.max(e.a.c, e.b.c);
      if (ec1 < c1 && c1 < ec2 && Math.min(r1, r2) < er && er < Math.max(r1, r2)) return true;
    }
  }
  return false;
}

/**
 * Baut eine zufällige, kreuzungsfreie Lösung.
 * @returns {{cols:number, rows:number, islands:{r:number,c:number}[], edges:{a:number,b:number,w:number}[]}|null}
 */
function growSolution(rng, target, cols, rows, doubleChance) {
  const islands = [];
  const edges = [];

  const start = { r: rng.range(0, rows - 1), c: rng.range(0, cols - 1) };
  islands.push(start);

  const isLeaf = (idx) => {
    let deg = 0;
    for (const e of edges) {
      if (e.a === idx || e.b === idx) deg++;
    }
    return deg <= 1;
  };

  let guard = 0;
  while (islands.length < target && guard < 5000) {
    guard++;
    const cands = [];
    const weights = [];

    for (let i = 0; i < islands.length; i++) {
      const isl = islands[i];
      for (const d of DIRS) {
        for (const dist of [1, 2]) {
          const nr = isl.r + d.dr * dist;
          const nc = isl.c + d.dc * dist;
          if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
          if (islandAt(islands, nr, nc)) continue;
          // Mittelfeld der Strecke muss frei sein (keine Brücke über eine Insel)
          if (dist === 2) {
            const mr = isl.r + d.dr;
            const mc = isl.c + d.dc;
            if (islandAt(islands, mr, mc)) continue;
          }
          if (liesOnBridge(edges, nr, nc)) continue;
          if (crossesExisting(edges, isl.r, isl.c, nr, nc)) continue;

          const candidateIslands = [...islands, { r: nr, c: nc }];
          const deg = visibleDegree(candidateIslands, nr, nc, rows, cols);

          let w = 1;
          if (isLeaf(i)) w *= 2.2; // Ketten weiterbauen -> organischere Form
          if (deg >= 4) w *= 0.05;
          else if (deg === 3) w *= 0.4;

          cands.push({ parent: i, r: nr, c: nc });
          weights.push(w);
        }
      }
    }

    if (cands.length === 0) break;
    const chosen = rng.pickWeighted(cands, weights);
    const id = islands.length;
    islands.push({ r: chosen.r, c: chosen.c });
    edges.push({ a: chosen.parent, b: id, w: rng.chance(doubleChance) ? 2 : 1 });
  }

  if (islands.length < 3) return null;
  return { cols, rows, islands, edges };
}

/* ------------------------------------------------------------------ *
 * Schritt 2: Lösung validieren, Zahlen ableiten
 * ------------------------------------------------------------------ */

/** Inselzahlen = Summe der anliegenden Brücken. */
export function numbersOf(sol) {
  const nums = new Array(sol.islands.length).fill(0);
  for (const e of sol.edges) {
    nums[e.a] += e.w;
    nums[e.b] += e.w;
  }
  return nums;
}

/** Prüft, ob die Lösung alle Regeln erfüllt. */
export function validateSolution(sol) {
  const { islands, edges } = sol;
  const seen = new Set();
  for (const i of islands) {
    if (i.r < 0 || i.r >= sol.rows || i.c < 0 || i.c >= sol.cols) return false;
    const k = key(i.r, i.c);
    if (seen.has(k)) return false;
    seen.add(k);
  }
  // Brücken dürfen nicht über Inseln führen
  for (const e of edges) {
    const a = islands[e.a];
    const b = islands[e.b];
    if (a.r === b.r) {
      for (let c = Math.min(a.c, b.c) + 1; c < Math.max(a.c, b.c); c++) {
        if (islandAt(islands, a.r, c)) return false;
      }
    } else {
      for (let r = Math.min(a.r, b.r) + 1; r < Math.max(a.r, b.r); r++) {
        if (islandAt(islands, r, a.c)) return false;
      }
    }
  }
  // Kreuzungen
  for (let i = 0; i < edges.length; i++) {
    for (let j = i + 1; j < edges.length; j++) {
      const e = edges[i];
      const f = edges[j];
      const eH = islands[e.a].r === islands[e.b].r;
      const fH = islands[f.a].r === islands[f.b].r;
      if (eH === fH) continue;
      const h = eH ? e : f;
      const v = eH ? f : e;
      const h1 = islands[h.a];
      const h2 = islands[h.b];
      const v1 = islands[v.a];
      const v2 = islands[v.b];
      const hMinC = Math.min(h1.c, h2.c);
      const hMaxC = Math.max(h1.c, h2.c);
      const vMinR = Math.min(v1.r, v2.r);
      const vMaxR = Math.max(v1.r, v2.r);
      const vCol = v1.c;
      const hRow = h1.r;
      if (hMinC < vCol && vCol < hMaxC && vMinR < hRow && hRow < vMaxR) return false;
    }
  }
  // Brückenzahlen 1..2
  for (const e of edges) {
    if (e.w < 1 || e.w > 2) return false;
  }
  // Inselzahlen <= 8
  const nums = numbersOf(sol);
  for (const n of nums) if (n < 1 || n > 8) return false;
  // Konnektivität
  const counts = new Array(edges.length).fill(0);
  edges.forEach((e, i) => {
    counts[i] = e.w;
  });
  const board = buildBoard(
    islands.map((s, i) => ({ id: i, r: s.r, c: s.c, num: nums[i] })),
    sol.cols,
    sol.rows,
  );
  return isConnected(board, counts);
}

/** Brettmodell aus einer Lösung bauen. */
function boardOf(sol, nums) {
  return buildBoard(
    sol.islands.map((s, i) => ({ id: i, r: s.r, c: s.c, num: nums[i] })),
    sol.cols,
    sol.rows,
  );
}

/** Brückenzahlen pro Brettkante aus der Lösung ableiten. */
function countsOf(board, sol) {
  const map = new Map();
  for (const e of sol.edges) map.set(edgeKey(e.a, e.b), e.w);
  return board.edges.map((e) => map.get(edgeKey(e.a, e.b)) ?? 0);
}

/* ------------------------------------------------------------------ *
 * Schritt 3: Reparatur -> eindeutige Lösung erzwingen
 * ------------------------------------------------------------------ */

/** Kopie der Lösung mit geänderter Brücke. */
function withEdge(sol, a, b, w) {
  const idx = sol.edges.findIndex((e) => edgeKey(e.a, e.b) === edgeKey(a, b));
  if (idx === -1) return null;
  const copy = {
    cols: sol.cols,
    rows: sol.rows,
    islands: sol.islands.map((i) => ({ ...i })),
    edges: sol.edges.map((e) => ({ ...e })),
  };
  if (w === 0) copy.edges.splice(idx, 1);
  else copy.edges[idx].w = w;
  return copy;
}

/**
 * Erzeugt Mutationen der Lösung:
 *  - Brückenstärke ändern (1 <-> 2)
 *  - zusätzliche Brücke auf einer freien Kante einziehen
 *  - Brücke entfernen
 */
function mutations(sol, board, rng) {
  const out = [];
  const used = new Set(sol.edges.map((e) => edgeKey(e.a, e.b)));

  // 1) Gewicht einer bestehenden Brücke ändern
  for (const e of sol.edges) {
    out.push(withEdge(sol, e.a, e.b, e.w === 1 ? 2 : 1));
  }

  // 2) Zusätzliche Brücke auf einer noch freien Kante
  for (let i = 0; i < board.edges.length; i++) {
    const e = board.edges[i];
    if (used.has(edgeKey(e.a, e.b))) continue;
    if (crossesExisting(sol.edges, board.islands[e.a].r, board.islands[e.a].c, board.islands[e.b].r, board.islands[e.b].c)) {
      continue;
    }
    out.push(withEdge(sol, e.a, e.b, 2));
    out.push(withEdge(sol, e.a, e.b, 1));
  }

  // 3) Brücke entfernen
  for (const e of sol.edges) {
    out.push(withEdge(sol, e.a, e.b, 0));
  }

  return out.filter(Boolean);
}

/**
 * Hill-Climbing: mutiert die Lösung, bis das Rätsel eindeutig lösbar ist.
 * @returns {object|null} die reparierte Lösung oder null
 */
function repair(sol, rng, maxIter) {
  let current = sol;
  let currentBoard = boardOf(current, numbersOf(current));
  let solutions = findSolutions(currentBoard, 3);
  let currentCount = solutions.length;
  let best = null;
  let bestCount = currentCount;

  for (let iter = 0; iter < maxIter; iter++) {
    if (currentCount === 1) {
      // Ziel erreicht: prüfen, ob die beabsichtigte Lösung die einzige ist
      const intended = countsOf(currentBoard, current);
      if (solutions.length === 1 && sameArray(solutions[0], intended)) return current;
      break;
    }
    if (currentCount === 0) return null; // ungültig -> neu versuchen

    // Gezielt eine Kante wählen, an der sich die beiden Lösungen unterscheiden
    let targetEdge = -1;
    if (solutions.length >= 2) {
      const diffs = [];
      for (let e = 0; e < currentBoard.edges.length; e++) {
        if (solutions[0][e] !== solutions[1][e]) diffs.push(e);
      }
      if (diffs.length) {
        const pick = currentBoard.edges[rng.pick(diffs)];
        targetEdge = currentBoard.edges.indexOf(pick);
      }
    }

    const options = mutations(current, currentBoard, rng);
    if (!options.length) break;

    // Mutationen priorisieren, die die gefundene Abweichung direkt treffen
    let chosen = null;
    if (targetEdge !== -1) {
      const te = currentBoard.edges[targetEdge];
      const focused = options.filter(
        (m) => m.edges.length !== current.edges.length || m.edges.some((e) => edgeKey(e.a, e.b) === edgeKey(te.a, te.b)),
      );
      if (focused.length) chosen = rng.pick(focused);
    }
    if (!chosen) chosen = rng.pick(options);

    if (!validateSolution(chosen)) continue;

    const chosenBoard = boardOf(chosen, numbersOf(chosen));
    const chosenSols = findSolutions(chosenBoard, 3);
    const chosenCount = chosenSols.length;

    if (chosenCount < currentCount || (chosenCount === currentCount && rng.chance(0.25))) {
      current = chosen;
      currentBoard = chosenBoard;
      solutions = chosenSols;
      currentCount = chosenCount;
      if (currentCount < bestCount) {
        bestCount = currentCount;
        best = chosen;
      }
    }
  }

  if (currentCount === 1) {
    const intended = countsOf(currentBoard, current);
    if (solutions.length === 1 && sameArray(solutions[0], intended)) return current;
  }
  return null;
}

/* ------------------------------------------------------------------ *
 * Schritt 4: Qualitätsbewertung & Auswahl
 * ------------------------------------------------------------------ */

function qualityScore(board, counts) {
  let score = 0;
  const nums = board.islands.map((i) => i.num);
  score += board.islands.length * 0.6;
  score += 2.0 * nums.filter((n) => n >= 3).length;
  score += 1.5 * nums.filter((n) => n >= 5).length;
  score += 0.8 * counts.filter((c) => c === 2).length;
  score += 1.2 * new Set(nums).size;
  score -= 0.5 * nums.filter((n) => n === 1).length;
  const rowsUsed = new Set(board.islands.map((i) => i.r)).size;
  const colsUsed = new Set(board.islands.map((i) => i.c)).size;
  score += 0.6 * (rowsUsed + colsUsed);
  return score;
}

/* ------------------------------------------------------------------ *
 * Notfall-Lösung: garantiert eindeutig lösbarer "Stern"
 * ------------------------------------------------------------------ */

/**
 * Kreuzförmiges Rätsel: ein Zentrum mit vier Armen.
 * Die Zentrumszahl erzwingt alle vier Verbindungen, die Arme sind
 * lineare Ketten -> genau eine Lösung. Dient als Absicherung, falls die
 * Zufallssuche kein eindeutiges Rätsel findet.
 */
function starFallback(cols, rows) {
  const cr = Math.floor(rows / 2);
  const cc = Math.floor(cols / 2);
  const islands = [{ r: cr, c: cc }];
  const edges = [];
  const arms = [
    { dr: -1, dc: 0 },
    { dr: 1, dc: 0 },
    { dr: 0, dc: -1 },
    { dr: 0, dc: 1 },
  ];
  for (const arm of arms) {
    const len = 2;
    let prev = 0;
    for (let s = 1; s <= len; s++) {
      const r = cr + arm.dr * s;
      const c = cc + arm.dc * s;
      if (r < 0 || r >= rows || c < 0 || c >= cols) break;
      const id = islands.length;
      islands.push({ r, c });
      edges.push({ a: prev, b: id, w: 1 });
      prev = id;
    }
  }
  const sol = { cols, rows, islands, edges };
  if (!validateSolution(sol)) return null;
  const board = boardOf(sol, numbersOf(sol));
  const counts = countsOf(board, sol);
  const sols = findSolutions(board, 2);
  if (sols.length !== 1 || !sameArray(sols[0], counts)) return null;
  return { sol, board, counts };
}

/* ------------------------------------------------------------------ *
 * Öffentliche API
 * ------------------------------------------------------------------ */

/**
 * Erzeugt ein neues Rätsel.
 *
 * @param {object} options
 * @param {string} [options.difficulty] 'easy' | 'medium' | 'hard' | 'expert'
 * @param {string} [options.seed]        Seed für reproduzierbare Rätsel
 */
export function generatePuzzle({ difficulty = 'medium', seed = randomSeed() } = {}) {
  const cfg = DIFFICULTIES[difficulty] ?? DIFFICULTIES.medium;
  const rng = new RNG(`${seed}|${difficulty}|hashi-v1`);

  let best = null;
  let bestScore = -Infinity;
  let valid = 0;

  for (let attempt = 0; attempt < cfg.tries; attempt++) {
    const target = rng.range(cfg.min, cfg.max);
    const sol = growSolution(rng, target, cfg.cols, cfg.rows, cfg.double);
    if (!sol) continue;
    if (!validateSolution(sol)) continue;

    let board = boardOf(sol, numbersOf(sol));
    let counts = countsOf(board, sol);
    let solutions = findSolutions(board, 3);

    if (solutions.length !== 1) {
      const fixed = repair(sol, rng, cfg.maxRepair);
      if (!fixed) continue;
      board = boardOf(fixed, numbersOf(fixed));
      counts = countsOf(board, fixed);
      solutions = findSolutions(board, 3);
      if (solutions.length !== 1) continue;
    }
    if (!sameArray(solutions[0], counts)) continue; // beabsichtigte Lösung != gefundene

    const score = qualityScore(board, counts);
    valid++;
    if (score > bestScore) {
      bestScore = score;
      best = { board, counts };
    }
    if (valid >= cfg.keep) break;
  }

  if (!best) {
    const fb = starFallback(cfg.cols, cfg.rows);
    if (!fb) throw new Error('Rätselgenerierung fehlgeschlagen');
    best = { board: fb.board, counts: fb.counts };
    bestScore = qualityScore(fb.board, fb.counts);
  }

  return {
    seed: String(seed),
    difficulty: cfg.id,
    difficultyLabel: cfg.label,
    cols: best.board.cols,
    rows: best.board.rows,
    islands: best.board.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
    edges: best.board.edges,
    solution: best.counts.slice(),
    score: Number(bestScore.toFixed(2)),
  };
}

