    const score = ev.status.consistent ? ev.status.determined : -1;
    if (score > bestScore) { bestScore = score; best = current; }
    const hood = buildNeighbourhood(current, ev.board, ev.nums, ev.status, rng);
    if (!hood.length) break;
    // sample
    const sample = rng.shuffle(hood.slice()).slice(0, 16);
    let chosen = null, chosenScore = score, chosenEv = ev;
    for (const cand of sample) {
