    if(a.r===b.r){for(let c=Math.min(a.c,b.c)+1;c<Math.max(a.c,b.c);c++) if(sol.islands.some(i=>i.r===a.r&&i.c===c)) reasons.push("Bruecke ueber Insel");}
    else {for(let r=Math.min(a.r,b.r)+1;r<Math.max(a.r,b.r);r++) if(sol.islands.some(i=>i.r===r&&i.c===a.c)) reasons.push("Bruecke ueber Insel");}
  }
  // Kreuzungen
  for(let i=0;i<sol.edges.length;i++)for(let j=i+1;j<sol.edges.length;j++){
    const e=sol.edges[i],f=sol.edges[j];
    const A=sol.islands[e.a],B=sol.islands[e.b],C=sol.islands[f.a],D=sol.islands[f.b];
    const eH=A.r===B.r, fH=C.r===D.r; if(eH===fH) continue;
    const h=eH?{a:A,b:B}:{a:C,b:D}, v=eH?{a:C,b:D}:{a:A,b:B};
    const hc=[h.a.c,h.b.c], vc=[v.a.c,v.b.c], hr=[h.a.r,h.b.r], vr=[v.a.r,v.b.r];
    if(Math.min(...hc)<v.a.c&&v.a.c<Math.max(...hc)&&Math.min(...vr)<h.a.r&&h.a.r<Math.max(...vr)) reasons.push("Kreuzung");
  }
  // Konnektivitaet
  const board = buildBoard(sol.islands.map((s,i)=>({id:i,r:s.r,c:s.c,num:nums[i]})),sol.cols,sol.rows);
  const counts=sol.edges.map(e=>e.w);
  if(!isConnected(board,counts)) reasons.push("nicht verbunden");
  return reasons;
}

for (const diff of ["medium","hard","expert"]) {
  const cfg=DIFFICULTIES[diff];
