Let me rewrite those functions.

For `liesOnBridge(islands, edges, r, c)`:
```js
function liesOnBridge(islands, edges, r, c) {
  for (const e of edges) {
    const a = islands[e.a], b = islands[e.b];
    if (a.r === b.r) {
      if (a.r === r && Math.min(a.c, b.c) < c && c < Math.max(a.c, b.c)) return true;
    } else if (a.c === b.c) {
      if (a.c === c && Math.min(a.r, b.r) < r && r < Math.max(a.r, b.r)) return true;
    }
  }
  return false;
}
```

For `crossesExisting(islands, edges, r1, c1, r2, c2)`:
```js
function crossesExisting(islands, edges, r1, c1, r2, c2) {
  const horizontal = r1 === r2;
  const cLo = Math.min(c1, c2), cHi = Math.max(c1, c2);
  const rLo = Math.min(r1, r2), rHi = Math.max(r1, r2);
  for (const e of edges) {
    const a = islands[e.a], b = islands[e.b];
    const eHorizontal = a.r === b.r;
    if (eHorizontal === horizontal) continue;
    if (horizontal) {
      const ec = a.c;
      const er1 = Math.min(a.r, b.r), er2 = Math.max(a.r, b.r);
      if (er1 < r1 && r1 < er2 && cLo < ec && ec < cHi) return true;
    } else {
      const er = a.r;
      const ec1 = Math.min(a.c, b.c), ec2 = Math.max(a.c, b.c);
      if (ec1 < c1 && c1 < ec2 && rLo < er && er < rHi) return true;
    }
  }
  return false;
}
```

