/**
 * Canvas-Renderer für das Hashi-Spielbrett.
 *
 * Zeichnet Brücken (einfach/doppelt), Inseln mit Zahl und optionale
 * Hervorhebungen (Auswahl, Hinweis, Fehler, Lösung). Trefferprüfung für
 * Maus- und Touch-Eingabe liegt ebenfalls hier.
 */

const FALLBACK_THEME = {
  ink: '#344054',
  island: '#1d2939',
  islandFg: '#ffffff',
  accent: '#4f46e5',
  accentSoft: '#eef2ff',
  correct: '#039855',
  wrong: '#d92d20',
  surface: '#ffffff',
  border: '#e4e7ec',
};

/** Liest die Farben aus den CSS-Custom-Properties (Light/Dark automatisch). */
export function readTheme() {
  if (typeof window === 'undefined' || !document?.documentElement) return { ...FALLBACK_THEME };
  const styles = getComputedStyle(document.documentElement);
  const pick = (name, fallback) => (styles.getPropertyValue(name) || '').trim() || fallback;
  return {
    ink: pick('--ink', FALLBACK_THEME.ink),
    island: pick('--island', FALLBACK_THEME.island),
    islandFg: pick('--island-fg', FALLBACK_THEME.islandFg),
    accent: pick('--accent', FALLBACK_THEME.accent),
    accentSoft: pick('--accent-soft', FALLBACK_THEME.accentSoft),
    correct: pick('--correct', FALLBACK_THEME.correct),
    wrong: pick('--wrong', FALLBACK_THEME.wrong),
    surface: pick('--surface', FALLBACK_THEME.surface),
    border: pick('--border', FALLBACK_THEME.border),
  };
}

function distToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  let t = len2 === 0 ? 0 : ((px - x1) * dx + (py - y1) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const cx = x1 + t * dx;
  const cy = y1 + t * dy;
  return Math.hypot(px - cx, py - cy);
}

export class BoardRenderer {
  /** @param {HTMLCanvasElement} canvas */
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.theme = readTheme();
    this.board = null;
    this.cell = 40;
    this.originX = 0;
    this.originY = 0;
    this.dpr = 1;
  }

  /** Liest die Theme-Farben neu (z. B. nach Theme-Wechsel). */
  refreshTheme() {
    this.theme = readTheme();
  }

  /** Passt die Canvas-Größe an den Container an und berechnet das Raster. */
  resize() {
    if (!this.board) return;
    const rect = this.canvas.parentElement.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const width = Math.max(240, Math.floor(rect.width));
    const height = Math.max(240, Math.floor(rect.height));

    this.canvas.width = Math.floor(width * dpr);
    this.canvas.height = Math.floor(height * dpr);
    this.canvas.style.width = `${width}px`;
    this.canvas.style.height = `${height}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.dpr = dpr;

    const cell = Math.min(width / this.board.cols, height / this.board.rows);
    this.cell = cell;
    this.originX = (width - cell * this.board.cols) / 2;
    this.originY = (height - cell * this.board.rows) / 2;
    this.width = width;
    this.height = height;
  }

  setBoard(board) {
    this.board = board;
    this.resize();
  }

  /** Mittelpunkt einer Zelle in Canvas-Koordinaten. */
  cellCenter(r, c) {
    return {
      x: this.originX + (c + 0.5) * this.cell,
      y: this.originY + (r + 0.5) * this.cell,
    };
  }

  get islandRadius() {
    return this.cell * 0.33;
  }

  /**
   * Trefferprüfung anhand von Canvas-Koordinaten.
   * @returns {{type:'island', island:object}|{type:'edge', edge:object}|null}
   */
  hitTest(px, py) {
    if (!this.board) return null;
    const R = this.islandRadius;

    for (const isl of this.board.islands) {
      const { x, y } = this.cellCenter(isl.r, isl.c);
      if (Math.hypot(px - x, py - y) <= R * 1.12) {
        return { type: 'island', island: isl };
      }
    }

    const tol = Math.max(this.cell * 0.16, 9);
    for (const edge of this.board.edges) {
      const a = this.cellCenter(this.board.islands[edge.a].r, this.board.islands[edge.a].c);
      const b = this.cellCenter(this.board.islands[edge.b].r, this.board.islands[edge.b].c);
      if (distToSegment(px, py, a.x, a.y, b.x, b.y) <= tol) {
        return { type: 'edge', edge };
      }
    }
    return null;
  }

  /**
   * Zeichnet das Brett.
   * @param {object} state
   * @param {Map<string, number>} state.bridges   Brückenzahl je Kanten-ID
   * @param {Set<string>}   [state.wrong]        als falsch markierte Kanten
   * @param {Set<string>}   [state.hint]         hervorzuhebende Kanten
   * @param {boolean}       [state.reveal]       Lösung komplett einblenden
   * @param {number|null}   [state.selected]     ausgewählte Insel
   * @param {object|null}   [state.preview]      Vorschau {edge, count}
   * @param {object|null}   [state.hover]        Hover-Kante
   */
  draw(state) {
    const ctx = this.ctx;
    if (!this.board || !ctx) return;
    const t = this.theme;

    ctx.clearRect(0, 0, this.width, this.height);

    const bridges = state.bridges ?? new Map();
    const wrong = state.wrong ?? new Set();
    const hint = state.hint ?? new Set();
    const reveal = state.reveal === true;

    // --- Brücken -----------------------------------------------------
    for (const edge of this.board.edges) {
      let count = bridges.get(edge.id) ?? 0;
      if (reveal) count = state.solution?.[this.board.edges.indexOf(edge)] ?? count;
      if (count <= 0) continue;

      const isWrong = wrong.has(edge.id);
      const isHint = hint.has(edge.id);
      const isHover = state.hover?.id === edge.id;

      let color = t.ink;
      if (isWrong) color = t.wrong;
      else if (isHint) color = t.accent;
      else if (reveal) color = t.accent;

      this.drawBridge(edge, count, color, isHover || isHint);
    }

    // Vorschau (Maus-Drag)
    if (state.preview && state.preview.count > 0) {
      this.drawBridge(state.preview.edge, state.preview.count, t.accent, true, 0.55);
    }

    // --- Inseln ------------------------------------------------------
    for (const isl of this.board.islands) {
      const { x, y } = this.cellCenter(isl.r, isl.c);
      const selected = state.selected === isl.id;

      if (selected) {
        ctx.beginPath();
        ctx.arc(x, y, this.islandRadius * 1.32, 0, Math.PI * 2);
        ctx.fillStyle = t.accentSoft;
        ctx.fill();
      }

      ctx.beginPath();
      ctx.arc(x, y, this.islandRadius, 0, Math.PI * 2);
      ctx.fillStyle = t.island;
      ctx.fill();

      if (selected) {
        ctx.lineWidth = Math.max(2, this.cell * 0.055);
        ctx.strokeStyle = t.accent;
        ctx.stroke();
      }

      const size = Math.round(this.islandRadius * 1.22);
      ctx.fillStyle = t.islandFg;
      ctx.font = `700 ${size}px ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(isl.num), x, y + size * 0.04);
    }
  }

  /** Zeichnet eine Brücke (einfach oder doppelt) zwischen zwei Inseln. */
  drawBridge(edge, count, color, emphasized = false, alpha = 1) {
    const ctx = this.ctx;
    const a = this.cellCenter(this.board.islands[edge.a].r, this.board.islands[edge.a].c);
    const b = this.cellCenter(this.board.islands[edge.b].r, this.board.islands[edge.b].c);

    const thickness = Math.max(2, this.cell * 0.085);
    const offset = this.cell * 0.095;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineWidth = emphasized ? thickness * 1.5 : thickness;
    if (emphasized) {
      ctx.shadowColor = color;
      ctx.shadowBlur = this.cell * 0.22;
    }

    const lines = count >= 2 ? [-offset, offset] : [0];
    for (const off of lines) {
      ctx.beginPath();
      if (edge.dir === 'h') {
        ctx.moveTo(a.x, a.y + off);
        ctx.lineTo(b.x, b.y + off);
      } else {
        ctx.moveTo(a.x + off, a.y);
        ctx.lineTo(b.x + off, b.y);
      }
      ctx.stroke();
    }
    ctx.restore();
  }
}

/* ==========================================================================
   Hashi – minimalistisches, modernes Design
   Farben über CSS-Custom-Properties, automatisches Hell/Dunkel-Schema.
   ========================================================================== */

:root {
  color-scheme: light dark;

  --bg: #f4f5f8;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --border: #e5e8ee;
  --border-strong: #d3d8e0;
  --text: #101828;
  --muted: #667085;
  --accent: #4f46e5;
  --accent-hover: #4338ca;
  --accent-soft: #eef2ff;
  --island: #1d2939;
  --island-fg: #ffffff;
  --ink: #344054;
  --correct: #039855;
  --wrong: #d92d20;

  --radius-sm: 10px;
  --radius: 14px;
  --radius-lg: 20px;
  --shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.05);
  --shadow: 0 4px 16px -4px rgba(16, 24, 40, 0.1), 0 2px 6px -2px rgba(16, 24, 40, 0.05);
  --shadow-lg: 0 24px 48px -12px rgba(16, 24, 40, 0.18);
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0b0e14;
    --surface: #12161f;
    --surface-2: #171c26;
    --border: #232a36;
    --border-strong: #333c4b;
    --text: #e7eaf0;
    --muted: #98a2b3;
    --accent: #818cf8;
    --accent-hover: #a5b4fc;
    --accent-soft: #1d2333;
    --island: #e7eaf0;
    --island-fg: #0b0e14;
    --ink: #9aa5b6;
    --correct: #32d583;
    --wrong: #f97066;
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
    --shadow: 0 4px 16px -4px rgba(0, 0, 0, 0.5);
    --shadow-lg: 0 24px 48px -12px rgba(0, 0, 0, 0.6);
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.app {
  max-width: 1140px;
  margin: 0 auto;
  padding: 20px 20px 32px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-height: 100vh;
}

/* ---------------------------------------------------------------- Header */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand__mark {
  width: 40px;
  height: 40px;
  flex: none;
}

.brand__bg {
  fill: var(--island);
}

.brand__island {
  fill: var(--surface);
}

.brand__bridge {
  fill: var(--surface);
  opacity: 0.85;
}

.brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand__name {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.brand__tag {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.topbar__stats {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  line-height: 1.15;
  padding: 4px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
}

.stat__label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.stat__value {
  font-size: 16px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.icon-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--border-strong);
}

.icon-btn:active {
  transform: scale(0.96);
}

.icon-btn svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn__moon {
  display: none;
}

@media (prefers-color-scheme: dark) {
  .icon-btn__sun {
    display: none;
  }
  .icon-btn__moon {
    display: block;
  }
}

/* ---------------------------------------------------------------- Layout */

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 288px;
  gap: 18px;
  align-items: start;
  flex: 1;
}

.board-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.board {
  position: relative;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-height: calc(100vh - 190px);
  margin-inline: auto;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  overflow: hidden;
  touch-action: none;
}

#board {
  display: block;
  width: 100%;
  height: 100%;
  cursor: pointer;
}

.status {
  margin: 0;
  min-height: 20px;
  text-align: center;
  font-size: 13px;
  color: var(--muted);
  transition: color 0.2s ease;
}

.status[data-tone="ok"] {
  color: var(--correct);
}

.status[data-tone="bad"] {
  color: var(--wrong);
}

.status[data-tone="hint"] {
  color: var(--accent);
}

/* ------------------------------------------------------------- Overlay */

.board__overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--surface) 78%, transparent);
  backdrop-filter: blur(6px);
  animation: fade-in 0.25s ease;
}

.board__overlay[hidden] {
  display: none;
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.win {
  text-align: center;
  padding: 26px 30px;
  border-radius: var(--radius-lg);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  animation: pop-in 0.3s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.win__badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-soft);
  padding: 5px 12px;
  border-radius: 999px;
}

.win__time {
  margin: 12px 0 2px;
  font-size: 34px;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.win__hint {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 13px;
}

.win__actions {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ---------------------------------------------------------------- Panel */

.panel {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field__label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.field__note {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

/* Segmented control */

.segmented {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
  padding: 4px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.segmented button {
  border: 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  padding: 7px 2px;
  border-radius: 9px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.segmented button:hover {
  color: var(--text);
}

.segmented button[aria-pressed="true"] {
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-sm);
}

.segmented button[aria-pressed="true"]::after {
  content: "";
}

/* Buttons */

.actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 12px;
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.12s ease, color 0.15s ease;
  white-space: nowrap;
}

.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--muted);
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: none;
}

.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  padding: 11px 12px;
}

.btn--primary:hover:not(:disabled) {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn--ghost {
  background: transparent;
  border-style: dashed;
  color: var(--muted);
}

.btn--ghost:hover:not(:disabled) {
  color: var(--text);
  background: var(--surface-2);
}

.btn--small {
  padding: 8px 12px;
  font-size: 13px;
}

/* Inputs */

.input {
  flex: 1;
  min-width: 0;
  padding: 8px 11px;
  font: inherit;
  font-size: 13px;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;
  letter-spacing: 0.04em;
  color: var(--text);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.input:focus {
  outline: none;
  border-color: var(--accent);
  background: var(--surface);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.seed-row {
  display: flex;
  gap: 8px;
}

/* Rules */

.rules {
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.rules summary {
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  list-style: none;
  display: flex;
  align-items: center;
  gap: 6px;
}

.rules summary::-webkit-details-marker {
  display: none;
}

.rules summary::before {
  content: "";
  width: 6px;
  height: 6px;
  border-right: 1.6px solid currentColor;
  border-bottom: 1.6px solid currentColor;
  transform: rotate(-45deg);
  transition: transform 0.2s ease;
}

.rules[open] summary::before {
  transform: rotate(45deg);
}

.rules ul {
  margin: 10px 0 0;
  padding-left: 18px;
  font-size: 13px;
  color: var(--muted);
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rules__tip {
  margin: 12px 0 0;
  font-size: 12.5px;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
}

.rules__tip strong {
  color: var(--text);
}

/* ---------------------------------------------------------------- Footer */

.footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--muted);
  padding-top: 4px;
}

kbd {
  display: inline-block;
  min-width: 18px;
  text-align: center;
  padding: 1px 5px;
  font: inherit;
  font-size: 11px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
}

/* ------------------------------------------------------------- Responsive */

@media (max-width: 860px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .board {
    max-height: none;
  }

  .panel {
    position: static;
  }

  .actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .actions > .btn--primary,
  .actions > .btn--ghost {
    grid-column: 1 / -1;
  }
}

@media (max-width: 520px) {
  .app {
    padding: 14px 14px 24px;
    gap: 14px;
  }

  .stat--hide-sm {
    display: none;
  }

  .segmented {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer__keys {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/**
 * Hashi – Spiellogik und Oberfläche.
 *
 * Zuständigkeiten:
 *  - `generatePuzzle` liefert ein garantiert eindeutig lösbares Rätsel
 *  - `BoardRenderer` zeichnet Brett und prüft Treffer
 *  - diese Datei verbindet beides: Spielzüge, Verlauf, Hinweise, Timer,
 *    Speichern und Teilen per Seed/Link.
 */

import { generatePuzzle, DIFFICULTIES, DIFFICULTY_IDS } from './generator.js';
import { randomSeed } from './rng.js';
import { BoardRenderer } from './render.js';

const STORAGE_KEY = 'hashi.state.v1';
const THEME_KEY = 'hashi.theme.v1';

const $ = (id) => document.getElementById(id);

const ui = {
  canvas: $('board'),
  boardWrap: $('boardWrap'),
  overlay: $('overlay'),
  winTime: $('winTime'),
  winHint: $('winHint'),
  winNew: $('winNew'),
  winClose: $('winClose'),
  timer: $('timer'),
  bridgeCount: $('bridgeCount'),
  status: $('status'),
  difficulty: $('difficulty'),
  newBtn: $('newBtn'),
  undoBtn: $('undoBtn'),
  redoBtn: $('redoBtn'),
  hintBtn: $('hintBtn'),
  checkBtn: $('checkBtn'),
  solveBtn: $('solveBtn'),
  seedInput: $('seedInput'),
  copyBtn: $('copyBtn'),
  themeBtn: $('themeBtn'),
};

const state = {
  board: null,
  solution: new Map(), // edgeId -> Brückenzahl der Lösung
  bridges: new Map(), // edgeId -> gesetzte Brücken
  history: [], // { edgeId, from, to }
  future: [],
  difficulty: 'medium',
  seed: '',
  elapsed: 0,
  running: false,
  solved: false,
  wrong: new Set(),
  hint: new Set(),
  preview: null,
  hover: null,
  selected: null,
  revealed: false,
  hintsUsed: 0,
};

const renderer = new BoardRenderer(ui.canvas);

/* ------------------------------------------------------------------ *
 * Hilfsfunktionen
 * ------------------------------------------------------------------ */

const fmtTime = (sec) => {
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
};

const islandLabel = (index) => {
  const isl = state.board?.islands[index];
  return isl ? `(${isl.r + 1}, ${isl.c + 1})` : '?';
};

function edgeBetween(aIndex, bIndex) {
  if (!state.board) return null;
  const neighbours = state.board.neighbors[aIndex] ?? [];
  const hit = neighbours.find((n) => n.other === bIndex);
  return hit ? state.board.edges[hit.edge] : null;
}

function setStatus(text, tone = '') {
  ui.status.textContent = text;
  ui.status.dataset.tone = tone;
}

/* ------------------------------------------------------------------ *
 * Rätsel starten
 * ------------------------------------------------------------------ */

function newPuzzle({ difficulty = state.difficulty, seed = randomSeed() } = {}) {
  const cfg = DIFFICULTIES[difficulty] ?? DIFFICULTIES.medium;
  const puzzle = generatePuzzle({ difficulty: cfg.id, seed });

  state.board = puzzle.edges && puzzle.islands ? buildBoardFromPuzzle(puzzle) : null;
  state.solution = new Map(state.board.edges.map((e, i) => [e.id, puzzle.solution[i]]));
  state.bridges = new Map();
  state.history = [];
  state.future = [];
  state.difficulty = cfg.id;
  state.seed = puzzle.seed;
  state.elapsed = 0;
  state.running = false;
  state.solved = false;
  state.wrong = new Set();
  state.hint = new Set();
  state.preview = null;
  state.hover = null;
  state.selected = null;
  state.revealed = false;
  state.hintsUsed = 0;

  renderer.setBoard(state.board);
  ui.seedInput.value = puzzle.seed;
  ui.overlay.hidden = true;
  syncDifficultyButtons();
  updateHash();
  save();
  render();
  setStatus(`${cfg.label} · ${state.board.islands.length} Inseln · Seed ${puzzle.seed}`);
}

/** Baut das Brettmodell aus dem Generator-Ergebnis. */
function buildBoardFromPuzzle(puzzle) {
  // Lazy Import vermeiden: buildBoard wird hier direkt synchronisiert geladen.
  return boardModule.buildBoard(
    puzzle.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
    puzzle.cols,
    puzzle.rows,
  );
}

/* ------------------------------------------------------------------ *
 * Spielzüge
 * ------------------------------------------------------------------ */

function setBridge(edgeId, count, { record = true } = {}) {
  const before = state.bridges.get(edgeId) ?? 0;
  if (before === count) return;
  if (count > 0) state.bridges.set(edgeId, count);
  else state.bridges.delete(edgeId);
  if (record) {
    state.history.push({ edgeId, from: before, to: count });
    state.future.length = 0;
  }
  clearFeedback();
  if (!state.solved) startTimer();
  checkSolved();
  render();
  save();
}

function cycleEdge(edge) {
  if (!edge) return;
  const current = state.bridges.get(edge.id) ?? 0;
  setBridge(edge.id, (current + 1) % 3);
}

function undo() {
  const move = state.history.pop();
  if (!move) return;
  const current = state.bridges.get(move.edgeId) ?? 0;
  if (current > 0) state.bridges.set(move.edgeId, current);
  else state.bridges.delete(move.edgeId);
  state.future.push(move);
  clearFeedback();
  render();
  save();
}

function redo() {
  const move = state.future.pop();
  if (!move) return;
  if (move.to > 0) state.bridges.set(move.edgeId, move.to);
  else state.bridges.delete(move.edgeId);
  state.history.push(move);
  clearFeedback();
  render();
  save();
}

/* ------------------------------------------------------------------ *
 * Hilfen
 * ------------------------------------------------------------------ */

function clearFeedback() {
  state.wrong.clear();
  state.hint.clear();
  state.revealed = false;
}

/** Prüft die aktuelle Lösung und markiert falsche Brücken. */
function check() {
  if (!state.board) return;
  state.hint.clear();
  state.revealed = false;
  let wrong = 0;
  let placed = 0;
  for (const [edgeId, count] of state.bridges) {
    placed++;
    if (state.solution.get(edgeId) !== count) {
      state.wrong.add(edgeId);
      wrong++;
    }
  }
  if (placed === 0) {
    setStatus('Noch keine Brücken gesetzt.');
    render();
    return;
  }
  if (wrong === 0) {
    setStatus('Alle gesetzten Brücken sind korrekt.', 'ok');
  } else {
    setStatus(`${wrong} von ${placed} Brücken sind falsch.`, 'bad');
  }
  render();
}

/** Setzt eine einzelne korrekte Brücke. */
function hint() {
  if (!state.board) return;
  state.wrong.clear();
  state.revealed = false;
  state.hint.clear();

  // Erst falsche Brücken korrigieren, dann fehlende ergänzen.
  for (const [edgeId, count] of state.bridges) {
    const target = state.solution.get(edgeId);
    if (target !== count) {
      state.hint.add(edgeId);
      const before = count;
      if (target > 0) state.bridges.set(edgeId, target);
      else state.bridges.delete(edgeId);
      state.history.push({ edgeId, from: before, to: target });
      state.future.length = 0;
      state.hintsUsed++;
      startTimer();
      checkSolved();
      render();
      save();
      const edge = state.board.edges.find((e) => e.id === edgeId);
      setStatus(
        target > 0
          ? `Hinweis: Brücke zwischen ${islandLabel(edge.a)} und ${islandLabel(edge.b)} korrigiert.`
          : `Hinweis: überflüssige Brücke zwischen ${islandLabel(edge.a)} und ${islandLabel(edge.b)} entfernt.`,
        'hint',
      );
      return;
    }
  }

  const missing = state.board.edges.find((e) => (state.bridges.get(e.id) ?? 0) !== state.solution.get(e.id));
  if (!missing) {
    setStatus('Das Rätsel ist bereits vollständig gelöst.', 'ok');
    render();
    return;
  }
  const target = state.solution.get(missing.id);
  const before = state.bridges.get(missing.id) ?? 0;
  if (target > 0) state.bridges.set(missing.id, target);
  else state.bridges.delete(missing.id);
  state.history.push({ edgeId: missing.id, from: before, to: target });
  state.future.length = 0;
  state.hint.add(missing.id);
  state.hintsUsed++;
  startTimer();
  checkSolved();
  render();
  save();
  setStatus(`Hinweis: Brücke zwischen ${islandLabel(missing.a)} und ${islandLabel(missing.b)} gesetzt.`, 'hint');
}

/** Zeigt die komplette Lösung. */
function solve() {
  if (!state.board) return;
  state.bridges = new Map();
  for (const [edgeId, count] of state.solution) {
    if (count > 0) state.bridges.set(edgeId, count);
  }
  state.history = [];
  state.future = [];
  state.wrong.clear();
  state.hint.clear();
  state.revealed = true;
  state.selected = null;
  render();
  save();
  setStatus('Lösung eingeblendet.', 'ok');
}

/* ------------------------------------------------------------------ *
 * Zustand
 * ------------------------------------------------------------------ */

function checkSolved() {
  if (!state.board || state.solved) return;
  for (const edge of state.board.edges) {
    if ((state.bridges.get(edge.id) ?? 0) !== (state.solution.get(edge.id) ?? 0)) return;
  }
  state.solved = true;
  state.running = false;
  ui.overlay.hidden = false;
  ui.winTime.textContent = fmtTime(state.elapsed);
  ui.winHint.textContent = state.hintsUsed
    ? `${state.hintsUsed} Hinweis${state.hintsUsed > 1 ? 'e' : ''} verwendet`
    : 'Ohne Hinweise gelöst';
  setStatus(`Gelöst in ${fmtTime(state.elapsed)}.`, 'ok');
  save();
}

function startTimer() {
  if (state.running || state.solved) return;
  state.running = true;
  ui.timer.textContent = fmtTime(state.elapsed);
}

function tick() {
  if (!state.running) return;
  state.elapsed++;
  ui.timer.textContent = fmtTime(state.elapsed);
}

/* ------------------------------------------------------------------ *
 * Speichern & Teilen
 * ------------------------------------------------------------------ */

function save() {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        seed: state.seed,
        difficulty: state.difficulty,
        elapsed: state.elapsed,
        solved: state.solved,
        hintsUsed: state.hintsUsed,
        bridges: [...state.bridges.entries()],
      }),
    );
  } catch {
    /* Speicher nicht verfügbar (z. B. privater Modus) – kein Problem. */
  }
}

function load() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function updateHash() {
  const hash = `#seed=${encodeURIComponent(state.seed)}&d=${state.difficulty}`;
  if (window.location.hash !== hash) {
    history.replaceState(null, '', hash);
  }
}

function readHash() {
  const params = new URLSearchParams(window.location.hash.replace(/^#/, ''));
  const seed = params.get('seed');
  const difficulty = params.get('d');
  return {
    seed: seed || null,
    difficulty: difficulty && DIFFICULTIES[difficulty] ? difficulty : null,
  };
}

async function copyLink() {
  updateHash();
  const url = window.location.href;
  try {
    await navigator.clipboard.writeText(url);
    setStatus('Link in die Zwischenablage kopiert.', 'ok');
  } catch {
    ui.seedInput.select();
    setStatus('Link konnte nicht kopiert werden – bitte manuell kopieren.', 'bad');
  }
}

/* ------------------------------------------------------------------ *
 * Darstellung
 * ------------------------------------------------------------------ */

function render() {
  renderer.draw({
    board: state.board,
    bridges: state.bridges,
    solution: state.solution,
    wrong: state.wrong,
    hint: state.hint,
    reveal: state.revealed,
    selected: state.selected,
    preview: state.preview,
    hover: state.hover,
  });
  ui.bridgeCount.textContent = String(state.bridges.size);
  ui.undoBtn.disabled = state.history.length === 0;
  ui.redoBtn.disabled = state.future.length === 0;
}

function syncDifficultyButtons() {
  for (const button of ui.difficulty.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(button.dataset.level === state.difficulty));
  }
}

/* ------------------------------------------------------------------ *
 * Eingabe
 * ------------------------------------------------------------------ */

function canvasPoint(event) {
  const rect = ui.canvas.getBoundingClientRect();
  return { x: event.clientX - rect.left, y: event.clientY - rect.top };
}

let press = null;

function onPointerDown(event) {
  if (!state.board) return;
  const point = canvasPoint(event);
  const hit = renderer.hitTest(point.x, point.y);
  if (!hit) {
    state.selected = null;
    render();
    return;
  }
  ui.canvas.setPointerCapture?.(event.pointerId);
  press = { hit, startX: event.clientX, startY: event.clientY, moved: false };
  if (hit.type === 'island') {
    state.selected = state.selected === hit.island.id ? null : hit.island.id;
    render();
  }
}

function onPointerMove(event) {
  if (!state.board) return;
  const point = canvasPoint(event);
  const hit = renderer.hitTest(point.x, point.y);

  // Hover-Hervorhebung einer Kante
  const hoverEdge = hit?.type === 'edge' ? hit.edge : null;
  if (hoverEdge?.id !== state.hover?.id) {
    state.hover = hoverEdge;
    render();
  }

  if (!press || press.hit.type !== 'island') return;
  const moved = Math.hypot(event.clientX - press.startX, event.clientY - press.startY) > 4;
  if (!moved) return;
  press.moved = true;

  if (hit?.type === 'island' && hit.island.id !== press.hit.island.id) {
    const edge = edgeBetween(press.hit.island.index, hit.island.index);
    if (edge) {
      const count = state.bridges.get(edge.id) ?? 0;
      state.preview = { edge, count: count === 0 ? 1 : count };
      render();
    }
  } else if (state.preview) {
    state.preview = null;
    render();
  }
}

function onPointerUp(event) {
  if (!press) return;
  const point = canvasPoint(event);
  const hit = renderer.hitTest(point.x, point.y);
  const start = press;
  press = null;
  state.preview = null;

  if (start.hit.type === 'edge') {
    if (!start.moved) cycleEdge(start.hit.edge);
    else render();
    return;
  }

  // Von einer Insel auf eine andere gezogen -> Brücke setzen
  if (start.moved && hit?.type === 'island' && hit.island.id !== start.hit.island.id) {
    const edge = edgeBetween(start.hit.island.index, hit.island.index);
    if (edge) {
      cycleEdge(edge);
      return;
    }
  }
  render();
}

function onPointerLeave() {
  state.preview = null;
  state.hover = null;
  press = null;
  render();
}

/* ------------------------------------------------------------------ *
 * Tastatur
 * ------------------------------------------------------------------ */

function onKeyDown(event) {
  const target = event.target;
  if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) return;
  if (event.metaKey || event.ctrlKey) {
    if (event.key.toLowerCase() === 'z') {
      event.preventDefault();
      if (event.shiftKey) redo();
      else undo();
    }
    return;
  }
  switch (event.key.toLowerCase()) {
    case 'n':
      newPuzzle({ difficulty: state.difficulty });
      break;
    case 'u':
    case 'z':
      undo();
      break;
    case 'r':
      redo();
      break;
    case 'h':
      hint();
      break;
    case 'c':
      check();
      break;
    case 's':
      solve();
      break;
    case 'escape':
      state.selected = null;
      render();
      break;
    default:
      break;
  }
}

/* ------------------------------------------------------------------ *
 * Theme
 * ------------------------------------------------------------------ */

function applyTheme(theme) {
  const root = document.documentElement;
  if (theme === 'auto') root.removeAttribute('data-theme');
  else root.setAttribute('data-theme', theme);
  renderer.refreshTheme();
  render();
}

function initTheme() {
  let theme = 'auto';
  try {
    theme = localStorage.getItem(THEME_KEY) || 'auto';
  } catch {
    theme = 'auto';
  }
  applyTheme(theme);
  ui.themeBtn.addEventListener('click', () => {
    const order = ['auto', 'light', 'dark'];
    const current = document.documentElement.getAttribute('data-theme') || 'auto';
    const next = order[(order.indexOf(current) + 1) % order.length];
    try {
      localStorage.setItem(THEME_KEY, next);
    } catch {
      /* ignorieren */
    }
    applyTheme(next);
    setStatus(`Farbschema: ${next === 'auto' ? 'automatisch' : next === 'light' ? 'hell' : 'dunkel'}`);
  });
}

/* ------------------------------------------------------------------ *
 * Start
 * ------------------------------------------------------------------ */

function buildDifficultyButtons() {
  for (const id of DIFFICULTY_IDS) {
    const cfg = DIFFICULTIES[id];
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.level = id;
    button.textContent = cfg.label;
    button.setAttribute('aria-pressed', 'false');
    button.addEventListener('click', () => newPuzzle({ difficulty: id }));
    ui.difficulty.appendChild(button);
  }
}

function setupEvents() {
  ui.canvas.addEventListener('pointerdown', onPointerDown);
  ui.canvas.addEventListener('pointermove', onPointerMove);
  ui.canvas.addEventListener('pointerup', onPointerUp);
  ui.canvas.addEventListener('pointercancel', onPointerUp);
  ui.canvas.addEventListener('pointerleave', onPointerLeave);
  ui.canvas.addEventListener('contextmenu', (e) => e.preventDefault());

  ui.newBtn.addEventListener('click', () => newPuzzle({ difficulty: state.difficulty }));
  ui.undoBtn.addEventListener('click', undo);
  ui.redoBtn.addEventListener('click', redo);
  ui.hintBtn.addEventListener('click', hint);
  ui.checkBtn.addEventListener('click', check);
  ui.solveBtn.addEventListener('click', solve);
  ui.copyBtn.addEventListener('click', copyLink);
  ui.winNew.addEventListener('click', () => newPuzzle({ difficulty: state.difficulty }));
  ui.winClose.addEventListener('click', () => {
    ui.overlay.hidden = true;
  });

  ui.seedInput.addEventListener('change', () => {
    const value = ui.seedInput.value.trim();
    if (!value) return;
    newPuzzle({ difficulty: state.difficulty, seed: value });
  });

  document.addEventListener('keydown', onKeyDown);

  const resize = () => {
    renderer.resize();
    render();
  };
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(resize).observe(ui.boardWrap);
  }
  window.addEventListener('resize', resize);
  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
    renderer.refreshTheme();
    render();
  });
}

function boot() {
  buildDifficultyButtons();
  setupEvents();
  initTheme();

  // Rätsel aus dem Link laden, sonst den zuletzt gespielten Stand.
  const fromHash = readHash();
  const stored = load();

  let difficulty = fromHash.difficulty ?? stored?.difficulty ?? 'medium';
  if (!DIFFICULTIES[difficulty]) difficulty = 'medium';
  let seed = fromHash.seed ?? stored?.seed ?? randomSeed();

  newPuzzle({ difficulty, seed });

  if (stored && !fromHash.seed && Array.isArray(stored.bridges)) {
    for (const [edgeId, count] of stored.bridges) {
      if (state.board.edges.some((e) => e.id === edgeId)) state.bridges.set(edgeId, count);
    }
    state.elapsed = stored.elapsed ?? 0;
    state.hintsUsed = stored.hintsUsed ?? 0;
    ui.timer.textContent = fmtTime(state.elapsed);
    if (stored.solved) {
      checkSolved();
    }
    render();
  }

  setInterval(tick, 1000);
}

boot();

