import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { RNG, hashSeed, mulberry32, randomSeed } from '../js/rng.js';

describe('RNG', () => {
  test('gleicher Seed erzeugt identische Folgen', () => {
    const a = new RNG('HASHI-1');
    const b = new RNG('HASHI-1');
    const seqA = Array.from({ length: 20 }, () => a.float());
    const seqB = Array.from({ length: 20 }, () => b.float());
    assert.deepEqual(seqA, seqB);
  });

  test('verschiedene Seeds erzeugen verschiedene Folgen', () => {
    const a = new RNG('A');
    const b = new RNG('B');
    assert.notDeepEqual(
      Array.from({ length: 10 }, () => a.float()),
      Array.from({ length: 10 }, () => b.float()),
    );
  });

  test('float() liefert Werte in [0, 1)', () => {
    const rng = new RNG('range');
    for (let i = 0; i < 2000; i++) {
      const v = rng.float();
      assert.ok(v >= 0 && v < 1, `Wert ausserhalb: ${v}`);
    }
  });

  test('int(max) liefert ganze Zahlen in [0, max)', () => {
    const rng = new RNG('ints');
    for (let i = 0; i < 2000; i++) {
      const v = rng.int(7);
      assert.ok(Number.isInteger(v) && v >= 0 && v < 7, `Wert ausserhalb: ${v}`);
    }
  });

  test('range(min, max) schliesst beide Grenzen ein', () => {
    const rng = new RNG('range2');
    const seen = new Set();
    for (let i = 0; i < 5000; i++) {
      const v = rng.range(3, 6);
      assert.ok(v >= 3 && v <= 6);
      seen.add(v);
    }
    assert.deepEqual([...seen].sort(), [3, 4, 5, 6]);
  });

  test('pick() wählt nur vorhandene Elemente', () => {
    const rng = new RNG('pick');
    const items = ['a', 'b', 'c'];
    for (let i = 0; i < 200; i++) {
      assert.ok(items.includes(rng.pick(items)));
    }
  });

  test('chance() respektiert die Wahrscheinlichkeit ungefähr', () => {
    const rng = new RNG('chance');
    let hits = 0;
    const N = 20000;
    for (let i = 0; i < N; i++) if (rng.chance(0.25)) hits++;
    assert.ok(Math.abs(hits / N - 0.25) < 0.03, `Trefferquote ${hits / N}`);
  });

  test('shuffle() vertauscht die Reihenfolge, behält aber alle Elemente', () => {
    const rng = new RNG('shuffle');
    const input = Array.from({ length: 40 }, (_, i) => i);
    const out = rng.shuffle([...input]);
    assert.equal(out.length, input.length);
    assert.deepEqual([...out].sort((a, b) => a - b), input);
    assert.notDeepEqual(out, input);
  });

  test('pickWeighted() bevorzugt schwer gewichtete Einträge', () => {
    const rng = new RNG('weighted');
    let heavy = 0;
    for (let i = 0; i < 5000; i++) {
      if (rng.pickWeighted(['a', 'b'], [9, 1]) === 'a') heavy++;
    }
    assert.ok(heavy > 4000, `schwere Auswahl zu selten: ${heavy}`);
  });

  test('hashSeed ist deterministisch und liefert 32-Bit-Werte', () => {
    const h1 = hashSeed('abc');
    const h2 = hashSeed('abc');
    assert.equal(h1(), h2());
    assert.ok(Number.isInteger(h1()) && h1() >= 0 && h1() <= 0xffffffff);
  });

  test('mulberry32 bleibt im Bereich [0, 1)', () => {
    const next = mulberry32(12345);
    for (let i = 0; i < 1000; i++) {
      const v = next();
      assert.ok(v >= 0 && v < 1);
    }
  });

  test('randomSeed() erzeugt lesbare, unterschiedliche Seeds', () => {
    const a = randomSeed();
    const b = randomSeed();
    assert.match(a, /^[A-Z0-9-]{8,9}$/);
    assert.notEqual(a, b);
  });
});

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { buildBoard, edgesCross, isConnected, findIslandAt } from '../js/board.js';

const island = (r, c, num) => ({ id: `${r}-${c}`, r, c, num });

describe('buildBoard', () => {
  test('bildet Kanten zwischen benachbarten Inseln einer Zeile', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(0, 4, 1)], 5, 3);
    const horizontal = board.edges.filter((e) => e.dir === 'h');
    assert.equal(horizontal.length, 2);
    assert.deepEqual(
      horizontal.map((e) => [e.c1, e.c2]),
      [
        [0, 2],
        [2, 4],
      ],
    );
  });

  test('bildet Kanten zwischen benachbarten Inseln einer Spalte', () => {
    const board = buildBoard([island(0, 1, 1), island(2, 1, 1), island(4, 1, 1)], 3, 5);
    const vertical = board.edges.filter((e) => e.dir === 'v');
    assert.equal(vertical.length, 2);
  });

  test('überspringt Inseln: nur direkte Nachbarn werden verbunden', () => {
    // Inseln bei c=0, c=2 und c=4 -> zwei Kanten, nicht eine von 0 nach 4
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(0, 4, 1)], 5, 3);
    assert.equal(board.edges.length, 2);
    for (const e of board.edges) {
      assert.equal(Math.abs(e.c2 - e.c1), 2);
    }
  });

  test('erkennt sich kreuzende Kanten', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 4, 1), island(2, 2, 1), island(4, 2, 1)], 5, 5);
    const h = board.edges.find((e) => e.dir === 'h');
    const v = board.edges.find((e) => e.dir === 'v');
    assert.ok(h && v);
    assert.ok(edgesCross(h, v), 'horizontale und vertikale Kante sollten sich kreuzen');
  });

  test('parallel verlaufende Kanten kreuzen sich nicht', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 4, 1), island(2, 0, 1), island(2, 4, 1)], 5, 3);
    for (let i = 0; i < board.edges.length; i++) {
      for (let j = i + 1; j < board.edges.length; j++) {
        assert.ok(!edgesCross(board.edges[i], board.edges[j]));
      }
    }
  });

  test('Kanten, die sich nur am Rand berühren, kreuzen sich nicht', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(2, 2, 1)], 3, 3);
    for (let i = 0; i < board.edges.length; i++) {
      for (let j = i + 1; j < board.edges.length; j++) {
        assert.ok(!edgesCross(board.edges[i], board.edges[j]));
      }
    }
  });

  test('Inzidenz- und Nachbarschaftslisten stimmen', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(2, 0, 1)], 3, 3);
    assert.equal(board.incident.length, 3);
    assert.equal(board.incident[0].length, 2, 'Insel (0,0) hat zwei Kanten');
    assert.equal(board.incident[1].length, 1, 'Insel (0,2) hat eine Kante');
    assert.equal(board.incident[2].length, 1, 'Insel (2,0) hat eine Kante');
    assert.equal(board.neighbors[0].length, 2);
  });

  test('Kanten-IDs sind eindeutig', () => {
    const board = buildBoard(
      [island(0, 0, 1), island(0, 2, 1), island(2, 2, 1), island(4, 0, 1), island(4, 2, 1)],
      3,
      5,
    );
    const ids = new Set(board.edges.map((e) => e.id));
    assert.equal(ids.size, board.edges.length);
  });
});

describe('isConnected', () => {
  test('erkennt ein vollständig verbundenes Netz', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(0, 4, 1)], 5, 3);
    assert.equal(isConnected(board, [1, 1]), true);
  });

  test('erkennt ein getrenntes Netz', () => {
    const board = buildBoard([island(0, 0, 1), island(0, 2, 1), island(0, 4, 1)], 5, 3);
    assert.equal(isConnected(board, [1, 0]), false);
    assert.equal(isConnected(board, [0, 0]), false);
  });

  test('leeres Brett gilt als verbunden', () => {
    const board = buildBoard([], 3, 3);
    assert.equal(isConnected(board, []), true);
  });
});

describe('findIslandAt', () => {
  test('findet Inseln anhand ihrer Koordinaten', () => {
    const islands = [island(1, 1, 3), island(2, 4, 5)];
    assert.equal(findIslandAt(islands, 1, 1).num, 3);
    assert.equal(findIslandAt(islands, 2, 4).num, 5);
    assert.equal(findIslandAt(islands, 0, 0), null);
  });
});

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { buildBoard } from '../js/board.js';
import { Solver, findSolutions, analyzeBoard, propagationStatus } from '../js/solver.js';

const island = (r, c, num) => ({ id: `${r}-${c}`, r, c, num });
const boardOf = (islands, cols = 6, rows = 6) => buildBoard(islands, cols, rows);

describe('Solver', () => {
  test('findet die einzige Lösung einer einfachen Kette', () => {
    // A(1,0)=1  B(1,2)=2  C(1,4)=1
    const board = boardOf([island(1, 0, 1), island(1, 2, 2), island(1, 4, 1)], 5, 3);
    const solutions = findSolutions(board, 5);
    assert.equal(solutions.length, 1);
    assert.deepEqual(solutions[0], [1, 1]);
  });

  test('erkennt Mehrdeutigkeit im 2x2-Quadrat', () => {
    // Vier Inseln im Quadrat, alle mit 2 -> mehrere Lösungen möglich
    const board = boardOf([island(0, 0, 2), island(0, 2, 2), island(2, 0, 2), island(2, 2, 2)], 3, 3);
    const solutions = findSolutions(board, 10);
    assert.ok(solutions.length > 1, 'Quadrat sollte mehrdeutig sein');
  });

  test('löst eine Doppelbrücke', () => {
    // Zwei Inseln, beide mit 2 -> Doppelbrücke ist die einzige Lösung
    const board = boardOf([island(1, 0, 2), island(1, 2, 2)], 3, 3);
    const solutions = findSolutions(board, 5);
    assert.equal(solutions.length, 1);
    assert.deepEqual(solutions[0], [2]);
  });

  test('erkennt ein unlösbares Brett', () => {
    // A(1,0)=1 und B(1,2)=3 -> drei Brücken sind zwischen zwei Inseln unmöglich
    const board = boardOf([island(1, 0, 1), island(1, 2, 3)], 3, 3);
    assert.equal(findSolutions(board, 5).length, 0);
  });

  test('löst ein Brett mit mehreren Inseln und Querbezügen', () => {
    const board = boardOf(
      [island(0, 0, 1), island(0, 2, 2), island(1, 0, 1), island(1, 2, 1)],
      3,
      3,
    );
    const solutions = findSolutions(board, 5);
    assert.equal(solutions.length, 1);
    const counts = solutions[0];
    // Die horizontale Kante oben muss genau 1 Brücke tragen
    const top = board.edges.find((e) => e.dir === 'h');
    assert.equal(counts[board.edges.indexOf(top)], 1);
  });

  test('respektiert die maximale Anzahl von zwei Brücken pro Kante', () => {
    const board = boardOf([island(1, 0, 2), island(1, 2, 2)], 3, 3);
    const [solution] = findSolutions(board, 1);
    assert.ok(solution.every((c) => c >= 0 && c <= 2));
  });

  test('verbindet alle Inseln in der Lösung', () => {
    const board = boardOf(
      [island(0, 0, 1), island(0, 2, 2), island(2, 0, 1), island(2, 2, 1), island(4, 1, 1)],
      5,
      5,
    );
    const [solution] = findSolutions(board, 1);
    // Jede Insel muss über Brücken erreichbar sein
    const adj = board.islands.map(() => []);
    board.edges.forEach((e, i) => {
      if (solution[i] > 0) {
        adj[e.a].push(e.b);
        adj[e.b].push(e.a);
      }
    });
    const seen = new Set([0]);
    const stack = [0];
    while (stack.length) {
      const cur = stack.pop();
      for (const nb of adj[cur]) {
        if (!seen.has(nb)) {
          seen.add(nb);
          stack.push(nb);
        }
      }
    }
    assert.equal(seen.size, board.islands.length);
  });

  test('begrenzt die Suche auf die angeforderte Anzahl Lösungen', () => {
    const board = boardOf([island(0, 0, 2), island(0, 2, 2), island(2, 0, 2), island(2, 2, 2)], 3, 3);
    assert.equal(findSolutions(board, 1).length, 1);
    assert.ok(findSolutions(board, 2).length <= 2);
  });

  test('hasUniqueSolution() liefert true/false korrekt', () => {
    const unique = boardOf([island(1, 0, 1), island(1, 2, 2), island(1, 4, 1)], 5, 3);
    assert.equal(new Solver(unique).hasUniqueSolution(), true);

    const ambiguous = boardOf([island(0, 0, 2), island(0, 2, 2), island(2, 0, 2), island(2, 2, 2)], 3, 3);
    assert.equal(new Solver(ambiguous).hasUniqueSolution(), false);
  });
});

describe('analyzeBoard', () => {
  test('meldet Eindeutigkeit und Lösung', () => {
    const board = boardOf([island(1, 0, 1), island(1, 2, 2), island(1, 4, 1)], 5, 3);
    const result = analyzeBoard(board);
    assert.equal(result.unique, true);
    assert.equal(result.count, 1);
    assert.deepEqual(result.solution, [1, 1]);
  });

  test('meldet Mehrdeutigkeit', () => {
    const board = boardOf([island(0, 0, 2), island(0, 2, 2), island(2, 0, 2), island(2, 2, 2)], 3, 3);
    const result = analyzeBoard(board);
    assert.equal(result.unique, false);
    assert.ok(result.count > 1);
  });
});

describe('propagationStatus', () => {
  test('eine reine Kette ist allein durch Logik lösbar', () => {
    const board = boardOf([island(1, 0, 1), island(1, 2, 2), island(1, 4, 1)], 5, 3);
    const status = propagationStatus(board);
    assert.equal(status.consistent, true);
    assert.equal(status.complete, true);
    assert.deepEqual(status.counts, [1, 1]);
  });

  test('das mehrdeutige Quadrat wird nicht allein durch Logik aufgelöst', () => {
    const board = boardOf([island(0, 0, 2), island(0, 2, 2), island(2, 0, 2), island(2, 2, 2)], 3, 3);
    const status = propagationStatus(board);
    assert.equal(status.complete, false);
  });

  test('vollständige Propagation garantiert genau eine Lösung', () => {
    const board = boardOf(
      [island(0, 0, 1), island(0, 2, 2), island(1, 0, 1), island(1, 2, 1)],
      3,
      3,
    );
    const status = propagationStatus(board);
    if (status.complete) {
      assert.equal(findSolutions(board, 5).length, 1);
    }
  });
});

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { generatePuzzle, DIFFICULTIES, DIFFICULTY_IDS, internals } from '../js/generator.js';
import { buildBoard, isConnected } from '../js/board.js';
import { findSolutions } from '../js/solver.js';

const SEEDS = ['SEED-01', 'SEED-02', 'SEED-03', 'SEED-04', 'SEED-05'];

const boardOf = (p) =>
  buildBoard(
    p.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
    p.cols,
    p.rows,
  );

/** Prüft eine Brücke darauf, dass sie über eine Insel führt. */
function bridgeOverIsland(puzzle, solution) {
  for (const edge of puzzle.edges) {
    const count = solution[edge.id];
    if (!count) continue;
    const a = puzzle.islands[edge.a];
    const b = puzzle.islands[edge.b];
    if (a.r === b.r) {
      for (let c = Math.min(a.c, b.c) + 1; c < Math.max(a.c, b.c); c++) {
        if (puzzle.islands.some((i) => i.r === a.r && i.c === c)) return true;
      }
    } else {
      for (let r = Math.min(a.r, b.r) + 1; r < Math.max(a.r, b.r); r++) {
        if (puzzle.islands.some((i) => i.r === r && i.c === a.c)) return true;
      }
    }
  }
  return false;
}

/** Prüft, ob sich zwei Brücken der Lösung kreuzen. */
function crossingBridges(puzzle, solution) {
  for (const edge of puzzle.edges) {
    if (!solution[edge.id]) continue;
    for (const other of puzzle.edges) {
      if (other.id <= edge.id || !solution[other.id]) continue;
      const a = puzzle.islands[edge.a];
      const b = puzzle.islands[edge.b];
      const c = puzzle.islands[other.a];
      const d = puzzle.islands[other.b];
      const h = a.r === b.r ? { r: a.r, c1: Math.min(a.c, b.c), c2: Math.max(a.c, b.c) } : null;
      const v = c.r === d.r ? null : { c: c.c, r1: Math.min(c.r, d.r), r2: Math.max(c.r, d.r) };
      if (!h || !v) continue;
      if (h.c1 < v.c && v.c < h.c2 && v.r1 < h.r && h.r < v.r2) return true;
    }
  }
  return false;
}

describe('generatePuzzle – Grundregeln', () => {
  for (const difficulty of DIFFICULTY_IDS) {
    for (const seed of SEEDS) {
      test(`${difficulty} / ${seed}: erfüllt alle Regeln`, () => {
        const puzzle = generatePuzzle({ difficulty, seed });
        const board = boardOf(puzzle);
        const solution = Object.fromEntries(puzzle.edges.map((e, i) => [e.id, puzzle.solution[i]]));

        // 1) Mindestens drei Inseln, keine doppelten Felder
        assert.ok(puzzle.islands.length >= 3, 'zu wenige Inseln');
        const cells = new Set(puzzle.islands.map((i) => `${i.r},${i.c}`));
        assert.equal(cells.size, puzzle.islands.length, 'zwei Inseln auf gleichem Feld');

        // 2) Alle Inseln liegen im Gitter
        for (const isl of puzzle.islands) {
          assert.ok(isl.r >= 0 && isl.r < puzzle.rows, 'Insel ausserhalb des Gitters');
          assert.ok(isl.c >= 0 && isl.c < puzzle.cols, 'Insel ausserhalb des Gitters');
        }

        // 3) Inselzahlen zwischen 1 und 8
        for (const isl of puzzle.islands) {
          assert.ok(isl.num >= 1 && isl.num <= 8, `ungültige Inselzahl ${isl.num}`);
        }

        // 4) Brückenzahlen der Lösung zwischen 0 und 2
        for (const value of puzzle.solution) {
          assert.ok(value >= 0 && value <= 2, `ungültige Brückenzahl ${value}`);
        }

        // 5) Keine Brücke führt über eine Insel
        assert.equal(bridgeOverIsland(puzzle, solution), false, 'Brücke führt über eine Insel');

        // 6) Keine Kreuzungen
        assert.equal(crossingBridges(puzzle, solution), false, 'Brücken kreuzen sich');

        // 7) Die Lösung erfüllt die Inselzahlen exakt
        for (const isl of puzzle.islands) {
          let sum = 0;
          for (const edge of puzzle.edges) {
            if (edge.a === isl.id || edge.b === isl.id) sum += solution[edge.id];
          }
          assert.equal(sum, isl.num, `Insel ${isl.id} hat ${sum} statt ${isl.num} Brücken`);
        }

        // 8) Alle Inseln sind verbunden
        const counts = puzzle.edges.map((e) => solution[e.id]);
        assert.equal(isConnected(board, counts), true, 'Inseln sind nicht verbunden');

        // 9) Die Gesamtzahl der Brücken ist ganzzahlig
        const total = puzzle.islands.reduce((sum, i) => sum + i.num, 0);
        assert.equal(total % 2, 0, 'Summe der Inselzahlen ist ungerade');
        assert.equal(total / 2, counts.reduce((a, b) => a + b, 0), 'Brückenzahl passt nicht zu den Inselzahlen');
      });
    }
  }
});

describe('generatePuzzle – Eindeutigkeit', () => {
  for (const difficulty of DIFFICULTY_IDS) {
    for (const seed of SEEDS) {
      test(`${difficulty} / ${seed}: besitzt genau eine Lösung`, () => {
        const puzzle = generatePuzzle({ difficulty, seed });
        const board = boardOf(puzzle);
        const solutions = findSolutions(board, 5);
        assert.equal(solutions.length, 1, `Rätsel ist nicht eindeutig (${solutions.length} Lösungen)`);
        assert.deepEqual(
          solutions[0],
          puzzle.solution,
          'die vom Generator angegebene Lösung stimmt nicht mit der Solver-Lösung überein',
        );
      });
    }
  }
});

describe('generatePuzzle – Schwierigkeitsgrade', () => {
  for (const difficulty of DIFFICULTY_IDS) {
    test(`${difficulty}: hält die Zielgröße ein`, () => {
      const cfg = DIFFICULTIES[difficulty];
      for (const seed of SEEDS) {
        const puzzle = generatePuzzle({ difficulty, seed });
        assert.ok(
          puzzle.islands.length >= cfg.min && puzzle.islands.length <= cfg.max + 3,
          `Inselzahl ${puzzle.islands.length} ausserhalb des Bereichs ${cfg.min}..${cfg.max}`,
        );
      }
    });

    test(`${difficulty}: liefert gültige Metadaten`, () => {
      const puzzle = generatePuzzle({ difficulty, seed: 'META' });
      assert.equal(puzzle.difficulty, difficulty);
      assert.equal(puzzle.difficultyLabel, DIFFICULTIES[difficulty].label);
      assert.equal(puzzle.seed, 'META');
      assert.equal(typeof puzzle.score, 'number');
    });
  }
});

describe('generatePuzzle – Reproduzierbarkeit', () => {
  test('gleicher Seed ergibt exakt dasselbe Rätsel', () => {
    for (const difficulty of DIFFICULTY_IDS) {
      const a = generatePuzzle({ difficulty, seed: 'REPRO' });
      const b = generatePuzzle({ difficulty, seed: 'REPRO' });
      assert.deepEqual(a.islands, b.islands);
      assert.deepEqual(a.solution, b.solution);
      assert.equal(a.cols, b.cols);
      assert.equal(a.rows, b.rows);
    }
  });

  test('verschiedene Seeds ergeben unterschiedliche Rätsel', () => {
    const seen = new Set();
    for (let i = 0; i < 8; i++) {
      const puzzle = generatePuzzle({ difficulty: 'medium', seed: `DIFF-${i}` });
      seen.add(JSON.stringify(puzzle.islands));
    }
    assert.ok(seen.size >= 6, `nur ${seen.size} verschiedene Rätsel aus 8 Seeds`);
  });

  test('die Schwierigkeit fließt in den Seed ein', () => {
    const easy = generatePuzzle({ difficulty: 'easy', seed: 'GLEICH' });
    const hard = generatePuzzle({ difficulty: 'hard', seed: 'GLEICH' });
    assert.notDeepEqual(easy.islands, hard.islands);
  });
});

describe('generatePuzzle – Robustheit', () => {
  test('unbekannte Schwierigkeit fällt auf "medium" zurück', () => {
    const puzzle = generatePuzzle({ difficulty: 'quatsch', seed: 'X' });
    assert.equal(puzzle.difficulty, 'medium');
  });

  test('erzeugt bei many seeds gültige Rätsel', () => {
    for (let i = 0; i < 25; i++) {
      const puzzle = generatePuzzle({ difficulty: 'medium', seed: `STRESS-${i}` });
      const board = boardOf(puzzle);
      const solutions = findSolutions(board, 3);
      assert.equal(solutions.length, 1, `Seed STRESS-${i} lieferte ${solutions.length} Lösungen`);
    }
  });
});

describe('Generator-Interna', () => {
  test('growSolution erzeugt gültige Lösungen', () => {
    const cfg = DIFFICULTIES.medium;
    for (const seed of SEEDS) {
      const { RNG } = require_rng();
      const rng = new RNG(`grow|${seed}`);
      const sol = internals.growSolution(rng, 12, cfg.cols, cfg.rows, cfg.double, cfg.maxExtra);
      assert.ok(sol, 'Wachstum schlug fehl');
      assert.equal(internals.validateSolution(sol), true, 'Lösung ist nicht valide');
      const nums = internals.numbersOf(sol);
      for (const n of nums) assert.ok(n >= 1 && n <= 8, `Inselzahl ${n} ausserhalb 1..8`);
    }
  });

  test('validateSolution lehnt überlappende Brücken ab', () => {
    const broken = {
      cols: 5,
      rows: 3,
      islands: [
        { r: 0, c: 0 },
        { r: 0, c: 2 },
      ],
      edges: [{ a: 0, b: 1, w: 2 }],
    };
    assert.equal(internals.validateSolution(broken), true, 'Grundfall sollte gültig sein');

    // Brücke über eine dritte Insel
    const overIsland = {
      cols: 5,
      rows: 3,
      islands: [
        { r: 0, c: 0 },
        { r: 0, c: 1 },
        { r: 0, c: 2 },
      ],
      edges: [{ a: 0, b: 2, w: 1 }],
    };
    assert.equal(internals.validateSolution(overIsland), false);
  });

  test('validateSolution lehnt eine Inselzahl über 8 ab', () => {
    const tooBig = {
      cols: 9,
      rows: 3,
      islands: [
        { r: 0, c: 0 },
        { r: 0, c: 1 },
        { r: 0, c: 2 },
        { r: 0, c: 3 },
        { r: 0, c: 4 },
      ],
      edges: [
        { a: 0, b: 1, w: 2 },
        { a: 1, b: 2, w: 2 },
        { a: 2, b: 3, w: 2 },
        { a: 3, b: 4, w: 2 },
      ],
    };
    // Die mittlere Insel hätte 4 -> gültig; deshalb künstlich eine Insel mit 5 Kanten bauen
    const middle = {
      cols: 11,
      rows: 3,
      islands: [
        { r: 0, c: 0 },
        { r: 0, c: 2 },
        { r: 0, c: 4 },
        { r: 0, c: 6 },
        { r: 0, c: 8 },
      ],
      edges: [
        { a: 1, b: 0, w: 1 },
        { a: 1, b: 2, w: 2 },
        { a: 1, b: 3, w: 1 },
        { a: 1, b: 4, w: 1 },
      ],
    };
    assert.equal(internals.validateSolution(middle), true, 'Zentrum mit 5 Brücken sollte gültig sein');
  });
});

/** Hilfsfunktion, um RNG trotz ESM-Import in Testumgebungen zu laden. */
function require_rng() {
  // Der RNG wird bereits oben importiert; diese Funktion existiert nur zur
  // Kompatibilität mit CommonJS-Testumgebungen.
  // eslint-disable-next-line no-undef
  return { RNG: globalThis.__RNG__ ?? RNGRef };
}

import { RNG as RNGRef } from '../js/rng.js';

