  tabID,
  script: `(() => {
    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const results = [];
    const count = () => document.getElementById('bridgeCount').textContent;

    // Mittelpunkt des Canvas -> dort klicken (erste Insel/Kante)
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;

    const fire = (type, x, y) => canvas.dispatchEvent(new PointerEvent(type, {
      clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, isPrimary: true
    }));

    // 1) Klick in die Mitte (Insel oder Kante)
    fire('pointerdown', cx, cy); fire('pointerup', cx, cy);
    results.push({ step: 'klick mitte', bruecken: count(), status: document.getElementById('status').textContent });

    // 2) Undo
    document.getElementById('undoBtn').click();
    results.push({ step: 'undo', bruecken: count() });

    // 3) Redo
    document.getElementById('redoBtn').click();
    results.push({ step: 'redo', bruecken: count() });

    // 4) Hinweis
    document.getElementById('hintBtn').click();
    results.push({ step: 'hinweis', bruecken: count(), status: document.getElementById('status').textContent });

    // 5) Pruefen
    document.getElementById('checkBtn').click();
    results.push({ step: 'pruefen', status: document.getElementById('status').textContent });

    // 6) Loesung zeigen
    document.getElementById('solveBtn').click();
    results.push({ step: 'loesung', bruecken: count(), status: document.getElementById('status').textContent });

    // 7) Tastatur: neues Rätsel
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'n', bubbles: true }));
    results.push({ step: 'neues raetsel', bruecken: count(), status: document.getElementById('status').textContent });

    return results;
  })()`
});
return r.value;

