const tabID = "tab_c7014849-742f-40f6-a989-39e340e27c33";
const r = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const gen = await import('./js/generator.js');
    const board = await import('./js/board.js');
    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const b = board.buildBoard(p.islands, p.cols, p.rows);

    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const cell = Math.min(rect.width / p.cols, rect.height / p.rows);
    const ox = rect.left + (rect.width - cell * p.cols) / 2;
    const oy = rect.top + (rect.height - cell * p.rows) / 2;
    const ctr = (r0, c0) => ({ x: ox + (c0 + 0.5) * cell, y: oy + (r0 + 0.5) * cell });

    const fire = (type, x, y) => canvas.dispatchEvent(new PointerEvent(type, {
      clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, isPrimary: true
    }));
    const count = () => document.getElementById('bridgeCount').textContent;

    const out = { seed, inseln: p.islands.length, kanten: b.edges.length };

    // 1) Auf eine Insel klicken -> Auswahl
    const isl = p.islands[0];
    const a = ctr(isl.r, isl.c);
    fire('pointerdown', a.x, a.y); fire('pointerup', a.x, a.y);
    out.nachInselKlick = count();

    // 2) Auf eine Kante klicken -> Bruecke
    const e = b.edges[0];
    const A = ctr(p.islands[e.a].r, p.islands[e.a].c);
    const B = ctr(p.islands[e.b].r, p.islands[e.b].c);
    const mid = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
    fire('pointerdown', mid.x, mid.y); fire('pointerup', mid.x, mid.y);
    out.nachKantenKlick = count();

    // 3) Erneut klicken -> Doppelbruecke
    fire('pointerdown', mid.x, mid.y); fire('pointerup', mid.x, mid.y);
    out.nachDoppeltKlick = count();

    // 4) Nochmal -> entfernt
    fire('pointerdown', mid.x, mid.y); fire('pointerup', mid.x, mid.y);
    out.nachDrittemKlick = count();

    // 5) Ziehen von Insel A nach Insel B
    const fire2 = (type, x, y) => canvas.dispatchEvent(new PointerEvent(type, {
      clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, isPrimary: true
    }));
    fire2('pointerdown', A.x, A.y);
    fire2('pointermove', mid.x, mid.y);
    fire2('pointerup', mid.x, mid.y);
    out.nachDrag = count();

    out.status = document.getElementById('status').textContent;
    return out;
  })()`
});
return r.value;

