/** Zeichnet die Hilfslinien (gepunktetes Raster) hinter dem Spielfeld. */
drawGrid() {
  const ctx = this.ctx;
  const t = this.theme;
  const { cols, rows } = this.board;
  const x0 = this.originX;
  const y0 = this.originY;
  const w = this.cell * cols;
  const h = this.cell * rows;

  ctx.save();
  ctx.strokeStyle = t.grid;
  ctx.lineWidth = 1;
  ctx.setLineDash([1.5, 4]);
  ctx.beginPath();
  for (let c = 0; c <= cols; c++) {
    const x = x0 + c * this.cell;
    ctx.moveTo(x, y0);
    ctx.lineTo(x, y0 + h);
  }
  for (let r = 0; r <= rows; r++) {
    const y = y0 + r * this.cell;
    ctx.moveTo(x0, y);
    ctx.lineTo(x0 + w, y);
  }
  ctx.stroke();
  ctx.restore();
}

/** Zeichnet den Rahmen um das Spielfeld. */
drawFrame() {
  const ctx = this.ctx;
  const t = this.theme;
  const { cols, rows } = this.board;
  const pad = this.cell * 0.16;
  const x = this.originX - pad;
  const y = this.originY - pad;
  const w = this.cell * cols + 2 * pad;
  const h = this.cell * rows + 2 * pad;
  const radius = Math.min(w, h) * 0.06;

  ctx.save();
  ctx.strokeStyle = t.frame;
  ctx.lineWidth = Math.max(1.25, this.cell * 0.035);
  ctx.beginPath();
  if (typeof ctx.roundRect === 'function') {
    ctx.roundRect(x, y, w, h, radius);
  } else {
    ctx.rect(x, y, w, h);
  }
  ctx.stroke();
  ctx.restore();
}

