/**
 * Rätselheft-Generator: erzeugt mehrere Hashi-Rätsel und setzt sie zu
 * Druckbögen im DIN-A6-Format zusammen (1, 2 oder 4 Rätsel pro Seite).
 */

import { generatePuzzle, DIFFICULTIES, DIFFICULTY_IDS } from './generator.js';
import { buildBoard } from './board.js';
import { randomSeed } from './rng.js';
import { boardToSvgElement, boardToSvgElementWithSolution } from './svg.js';

const $ = (id) => document.getElementById(id);

const ui = {
  difficulty: $('difficulty'),
  perPage: $('perPage'),
  count: $('count'),
  seedInput: $('seedInput'),
  copyBtn: $('copyBtn'),
  withSolutions: $('withSolutions'),
  generateBtn: $('generateBtn'),
  printBtn: $('printBtn'),
  sheets: $('sheets'),
  info: $('bookletInfo'),
};

const state = {
  difficulty: 'medium',
  perPage: 4,
  count: 8,
  seed: randomSeed(),
  withSolutions: true,
  puzzles: [],
};

/* ------------------------------------------------------------------ *
 * Erzeugung
 * ------------------------------------------------------------------ */

function buildPuzzles() {
  const puzzles = [];
  for (let i = 0; i < state.count; i++) {
    const seed = `${state.seed}-${i + 1}`;
    const puzzle = generatePuzzle({ difficulty: state.difficulty, seed });
    const board = buildBoard(
      puzzle.islands.map((isl) => ({ id: isl.id, r: isl.r, c: isl.c, num: isl.num })),
      puzzle.cols,
      puzzle.rows,
    );
    puzzles.push({ ...puzzle, board, seed });
  }
  return puzzles;
}

/* ------------------------------------------------------------------ *
 * Darstellung
 * ------------------------------------------------------------------ */

/** Erzeugt ein einzelnes Rätsel-Element (Mini-Version). */
function miniPuzzle(puzzle, index, { solution = false } = {}) {
  const article = document.createElement('article');
  article.className = 'mini';

  const head = document.createElement('header');
  head.className = 'mini__head';
  const no = document.createElement('span');
  no.className = 'mini__no';
  no.textContent = solution ? 'L' : String(index + 1);
  const label = document.createElement('span');
  label.className = 'mini__label';
  label.textContent = solution ? 'Lösung' : DIFFICULTIES[state.difficulty].label;
  head.append(no, label);

  const board = document.createElement('div');
  board.className = 'mini__board';
  board.appendChild(
    solution
      ? boardToSvgElementWithSolution(puzzle.board, puzzle.solution)
      : boardToSvgElement(puzzle.board),
  );

  const foot = document.createElement('footer');
  foot.className = 'mini__foot';
  foot.textContent = puzzle.seed;

  article.append(head, board, foot);
  return article;
}

/** Erzeugt einen Druckbogen (A6) mit den übergebenen Rätseln. */
function buildSheet(puzzles, { solution = false, perPage = state.perPage } = {}) {
  const section = document.createElement('section');
  section.className = 'sheet';
  section.dataset.per = String(perPage);

  const grid = document.createElement('div');
  grid.className = 'sheet__grid';
  grid.dataset.per = String(perPage);

  puzzles.forEach((puzzle, i) => {
    grid.appendChild(miniPuzzle(puzzle, i, { solution }));
  });

  section.appendChild(grid);
  return section;
}

function render() {
  const puzzles = state.puzzles;
  const perPage = state.perPage;
  const sheets = [];

  for (let i = 0; i < puzzles.length; i += perPage) {
    sheets.push(buildSheet(puzzles.slice(i, i + perPage), { perPage }));
  }

  if (state.withSolutions) {
    for (let i = 0; i < puzzles.length; i += perPage) {
      sheets.push(buildSheet(puzzles.slice(i, i + perPage), { solution: true, perPage }));
    }
  }

  ui.sheets.replaceChildren(...sheets);

  const puzzlePages = Math.ceil(puzzles.length / perPage);
  const solutionPages = state.withSolutions ? puzzlePages : 0;
  ui.info.textContent = `${puzzles.length} Rätsel · ${puzzlePages} Seiten${
    state.withSolutions ? ` + ${solutionPages} Lösungsseiten` : ''
  } · DIN A6 · Seed ${state.seed}`;
}

/* ------------------------------------------------------------------ *
 * Bedienung
 * ------------------------------------------------------------------ */

function syncGroups() {
  for (const button of ui.difficulty.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(button.dataset.level === state.difficulty));
  }
  for (const button of ui.perPage.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(Number(button.dataset.per) === state.perPage));
  }
  for (const button of ui.count.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(Number(button.dataset.count) === state.count));
  }
}

function updateHash() {
  const params = new URLSearchParams({
    seed: state.seed,
    d: state.difficulty,
    n: String(state.count),
    per: String(state.perPage),
  });
  if (state.withSolutions) params.set('sol', '1');
  const hash = `#${params.toString()}`;
  if (window.location.hash !== hash) history.replaceState(null, '', hash);
}

function readHash() {
  const params = new URLSearchParams(window.location.hash.replace(/^#/, ''));
  const out = {};
  const seed = params.get('seed');
  const d = params.get('d');
  const n = Number(params.get('n'));
  const per = Number(params.get('per'));
  if (seed) out.seed = seed;
  if (d && DIFFICULTIES[d]) out.difficulty = d;
  if ([4, 8, 12, 20].includes(n)) out.count = n;
  if ([1, 2, 4].includes(per)) out.perPage = per;
  if (params.get('sol') === '1') out.withSolutions = true;
  return out;
}

async function copyLink() {
  updateHash();
  try {
    await navigator.clipboard.writeText(window.location.href);
    ui.info.textContent = 'Link in die Zwischenablage kopiert.';
  } catch {
    ui.seedInput.select();
  }
}

function generate() {
  ui.generateBtn.disabled = true;
  ui.generateBtn.textContent = 'Wird erzeugt …';
  // Kurze Verzögerung, damit die Oberfläche den Klick verarbeiten kann
  setTimeout(() => {
    state.puzzles = buildPuzzles();
    updateHash();
    render();
    ui.generateBtn.disabled = false;
    ui.generateBtn.innerHTML =
      '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg> Heft erzeugen';
  }, 30);
}

/* ------------------------------------------------------------------ *
 * Start
 * ------------------------------------------------------------------ */

function buildDifficultyButtons() {
  for (const id of DIFFICULTY_IDS) {
    const cfg = DIFFICULTIES[id];
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.level = id;
    button.textContent = cfg.label;
    button.setAttribute('aria-pressed', 'false');
    button.addEventListener('click', () => {
      state.difficulty = id;
      syncGroups();
      generate();
    });
    ui.difficulty.appendChild(button);
  }
}

function setupEvents() {
  for (const button of ui.perPage.querySelectorAll('button')) {
    button.addEventListener('click', () => {
      state.perPage = Number(button.dataset.per);
      syncGroups();
      render();
      updateHash();
    });
  }

  for (const button of ui.count.querySelectorAll('button')) {
    button.addEventListener('click', () => {
      state.count = Number(button.dataset.count);
      syncGroups();
      generate();
    });
  }

  ui.withSolutions.addEventListener('change', () => {
    state.withSolutions = ui.withSolutions.checked;
    render();
    updateHash();
  });

  ui.seedInput.addEventListener('change', () => {
    const value = ui.seedInput.value.trim();
    if (!value) return;
    state.seed = value;
    generate();
  });

  ui.generateBtn.addEventListener('click', generate);
  ui.copyBtn.addEventListener('click', copyLink);
  ui.printBtn.addEventListener('click', () => window.print());

  document.addEventListener('keydown', (event) => {
    const target = event.target;
    if (target instanceof HTMLInputElement) return;
    if (event.key.toLowerCase() === 'n' && !event.metaKey && !event.ctrlKey) {
      event.preventDefault();
      state.seed = randomSeed();
      ui.seedInput.value = state.seed;
      generate();
    }
  });
}

function boot() {
  buildDifficultyButtons();

  const fromHash = readHash();
  Object.assign(state, fromHash);
  ui.seedInput.value = state.seed;
  ui.withSolutions.checked = state.withSolutions;

  setupEvents();
  syncGroups();
  generate();
}

boot();

/* ==========================================================================
   Rätselheft – Layout der Druckbögen (DIN A6) und der Vorschau
   ========================================================================== */

.booklet-body {
  background: var(--bg);
}

.booklet__main {
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
  flex: 1;
}

.booklet__controls {
  position: sticky;
  top: 18px;
}

.booklet__preview {
  min-width: 0;
}

.segmented--3 {
  grid-template-columns: repeat(3, 1fr);
}

.segmented--4 {
  grid-template-columns: repeat(4, 1fr);
}

.checkbox {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13.5px;
  color: var(--text);
  cursor: pointer;
  user-select: none;
}

.checkbox input {
  width: 16px;
  height: 16px;
  accent-color: var(--accent);
  cursor: pointer;
}

/* ------------------------------------------------------------- Druckbogen */

.sheets {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
}

.sheet {
  width: 105mm;
  height: 148mm;
  flex: none;
  background: #fff;
  color: #000;
  border: 1px solid var(--border);
  border-radius: 4px;
  box-shadow: var(--shadow);
  padding: 7mm;
  overflow: hidden;
  display: flex;
}

.sheet__grid {
  display: grid;
  gap: 4mm;
  width: 100%;
  height: 100%;
}

.sheet__grid[data-per="1"] {
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
}

.sheet__grid[data-per="2"] {
  grid-template-columns: 1fr;
  grid-template-rows: repeat(2, 1fr);
}

.sheet__grid[data-per="4"] {
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: repeat(2, 1fr);
}

/* --------------------------------------------------------- Einzelnes Rätsel */

.mini {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  break-inside: avoid;
}

.mini__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 3mm;
  font-size: 7pt;
  line-height: 1;
  margin-bottom: 1.5mm;
}

.mini__no {
  font-weight: 700;
  font-size: 9pt;
}

.mini__label {
  color: #555;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 6.4pt;
}

.mini__board {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mini__board .board-svg {
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
}

.mini__foot {
  margin-top: 1.5mm;
  font-size: 5.6pt;
  color: #888;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0.03em;
}

/* ----------------------------------------------------------------- Druck */

@media print {
  @page {
    size: A6 portrait;
    margin: 0;
  }

  html,
  body {
    background: #fff !important;
  }

  .booklet__controls,
  .topbar,
  .footer {
    display: none !important;
  }

  .booklet__main {
    display: block;
  }

  .sheets {
    display: block;
    gap: 0;
  }

  .sheet {
    width: 105mm;
    height: 148mm;
    margin: 0;
    padding: 6mm;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    break-after: page;
    page-break-after: always;
  }

  .sheet:last-child {
    break-after: auto;
    page-break-after: auto;
  }
}

@media (max-width: 900px) {
  .booklet__main {
    grid-template-columns: minmax(0, 1fr);
  }

  .booklet__controls {
    position: static;
  }

  .sheets {
    overflow-x: auto;
    align-items: flex-start;
  }
}

