const state = {
  difficulty: 'medium',
  perPage: 2,
  count: 8,
  seed: randomSeed(),
  withSolutions: true,
  puzzles: [],
};

/* ------------------------------------------------------------------ *
 * Seitenaufteilung (DIN A6)
 * ------------------------------------------------------------------ */

/** Nutzbare Fläche einer A6-Seite in Millimetern (105 × 148 abzüglich Rand). */
const PAGE = { width: 93, height: 136 };

/** Platz, den Kopf- und Fusszeile eines Rätsels brauchen. */
const CHROME = { one: 10, two: 10 };

/**
 * Kleinste noch lesbare Rasterzelle in Millimetern.
 * Darunter wird ein zweites Rätsel nicht mehr auf dieselbe Seite gelegt.
 */
const MIN_CELL_MM = 6;

/**
 * Grössere einer Rasterzelle in Millimetern, wenn das Rätsel
 * mit `perPage` Rätseln pro Seite gedruckt wird.
 */
function cellSizeMm(puzzle, perPage) {
  const availH = perPage === 2 ? PAGE.height / 2 - CHROME.two : PAGE.height - CHROME.one;
  const availW = PAGE.width;
  // Das SVG enthält einen kleinen Rand um das Spielfeld
  const viewW = puzzle.cols + 0.24;
  const viewH = puzzle.rows + 0.24;
  return Math.min(availW / viewW, availH / viewH);
}

/**
 * Verteilt die Rätsel auf Seiten.
 * Pro Seite passen höchstens zwei Rätsel. Sind die Raster zu gross für
 * zwei Rätsel, wird die Seite mit nur einem Rätsel belegt.
 */
function groupIntoPages(puzzles, maxPerPage = 2) {
  const pages = [];
  let i = 0;
  while (i < puzzles.length) {
    const first = puzzles[i];
    const second = puzzles[i + 1];
    const fitsTwo =
      maxPerPage >= 2 &&
      second &&
      cellSizeMm(first, 2) >= MIN_CELL_MM &&
      cellSizeMm(second, 2) >= MIN_CELL_MM;
    if (fitsTwo) {
      pages.push([first, second]);
      i += 2;
    } else {
      pages.push([first]);
      i += 1;
    }
  }
  return pages;
}

