/* ------------------------------------------------------------------ *
 * Seitenaufteilung (DIN A6)
 * ------------------------------------------------------------------ */

/** Nutzbare Fläche einer A6-Seite in Millimetern (105 × 148 abzüglich Rand). */
const PAGE = { width: 93, height: 136 };

/** Abstand zwischen zwei Rätseln auf derselben Seite. */
const GAP = 4;

/** Platz, den Kopf- und Fusszeile eines Rätsels brauchen. */
const CHROME = 8;

/**
 * Kleinste noch lesbare Rasterzelle in Millimetern.
 * Darunter wird ein zweites Rätsel nicht mehr auf dieselbe Seite gelegt.
 */
const MIN_CELL_MM = 6;

/** Anordnung der Rätsel auf einem Bogen. */
const LAYOUTS = {
  row: { cols: 1, rows: 2 }, // untereinander
  col: { cols: 2, rows: 1 }, // nebeneinander
};

/**
 * Grössere einer Rasterzelle in Millimetern, wenn das Rätsel in der
 * angegebenen Anordnung gedruckt wird.
 */
function cellSizeMm(puzzle, layout, count) {
  const grid = count === 1 ? { cols: 1, rows: 1 } : LAYOUTS[layout];
  const availW = (PAGE.width - (grid.cols - 1) * GAP) / grid.cols - CHROME * 0.25;
  const availH = (PAGE.height - (grid.rows - 1) * GAP) / grid.rows - CHROME;
  // Das SVG enthält einen kleinen Rand um das Spielfeld
  return Math.min(availW / (puzzle.cols + 0.24), availH / (puzzle.rows + 0.24));
}

/**
 * Wählt die Anordnung, bei der die Rasterzellen am grössten werden.
 * Breite Raster profitieren von der Stapel-Anordnung, hohe Raster von der
 * Anordnung nebeneinander.
 */
function bestLayout(puzzles) {
  if (puzzles.length < 2) return 'row';
  let best = 'row';
  let bestSize = -Infinity;
  for (const layout of ['row', 'col']) {
    const size = Math.min(...puzzles.map((p) => cellSizeMm(p, layout, 2)));
    if (size > bestSize) {
      bestSize = size;
      best = layout;
    }
  }
  return best;
}

/**
 * Verteilt die Rätsel auf Seiten.
 * Pro Seite passen höchstens zwei Rätsel. Sind die Raster zu gross für
 * zwei Rätsel, wird die Seite mit nur einem Rätsel belegt.
 */
function groupIntoPages(puzzles, maxPerPage = 2) {
  const pages = [];
  let i = 0;
  while (i < puzzles.length) {
    const first = puzzles[i];
    const second = puzzles[i + 1];
    const two = second ? [first, second] : null;
    const fitsTwo =
      maxPerPage >= 2 &&
      two &&
      cellSizeMm(first, 'row', 2) >= MIN_CELL_MM &&
      cellSizeMm(second, 'row', 2) >= MIN_CELL_MM;
    if (fitsTwo) {
      pages.push(two);
      i += 2;
    } else {
      pages.push([first]);
      i += 1;
    }
  }
  return pages;
}

