/** Setzt eine einzelne korrekte Brücke. */
function hint() {
  if (!state.board) return;
  state.wrong.clear();
  state.revealed = false;
  state.hint.clear();

  // Erst falsche Brücken korrigieren, dann fehlende ergänzen.
  for (const [edgeId, count] of state.bridges) {
    const target = state.solution.get(edgeId);
    if (target !== count) {
      state.hint.add(edgeId);
      const before = count;
      if (target > 0) state.bridges.set(edgeId, target);
      else state.bridges.delete(edgeId);
      state.history.push({ edgeId, from: before, to: target });
      state.future.length = 0;
      state.hintsUsed++;
      startTimer();
      checkSolved();
      render();
      save();
      const edge = state.board.edges.find((e) => e.id === edgeId);
      setStatus(
        target > 0
          ? `Hinweis: Brücke zwischen ${islandLabel(edge.a)} und ${islandLabel(edge.b)} korrigiert.`
          : `Hinweis: überflüssige Brücke zwischen ${islandLabel(edge.a)} und ${islandLabel(edge.b)} entfernt.`,
        'hint',
      );
      return;
    }
  }

  const missing = state.board.edges.find((e) => (state.bridges.get(e.id) ?? 0) !== state.solution.get(e.id));
  if (!missing) {
    setStatus('Das Rätsel ist bereits vollständig gelöst.', 'ok');
    render();
    return;
  }
  const target = state.solution.get(missing.id);
  const before = state.bridges.get(missing.id) ?? 0;
  if (target > 0) state.bridges.set(missing.id, target);
  else state.bridges.delete(missing.id);
  state.history.push({ edgeId: missing.id, from: before, to: target });
  state.future.length = 0;
  state.hint.add(missing.id);
  state.hintsUsed++;
  startTimer();
  checkSolved();
  render();
  save();
  setStatus(`Hinweis: Brücke zwischen ${islandLabel(missing.a)} und ${islandLabel(missing.b)} gesetzt.`, 'hint');
}

/** Zeigt die komplette Lösung. */
function solve() {
  if (!state.board) return;
  state.bridges = new Map();
  for (const [edgeId, count] of state.solution) {
    if (count > 0) state.bridges.set(edgeId, count);
  }
  state.history = [];
  state.future = [];
  state.wrong.clear();
  state.hint.clear();
  state.revealed = true;
  state.selected = null;
  checkSolved();
  render();
  save();
  if (!state.solved) setStatus('Lösung eingeblendet.', 'ok');
}

/* ------------------------------------------------------------------ *
 * Zustand
 * ------------------------------------------------------------------ */

function checkSolved() {
  if (!state.board || state.solved) return;
  for (const edge of state.board.edges) {
    if ((state.bridges.get(edge.id) ?? 0) !== (state.solution.get(edge.id) ?? 0)) return;
  }
  state.solved = true;
  state.running = false;
  ui.overlay.hidden = false;
  ui.winTime.textContent = fmtTime(state.elapsed);
  ui.winHint.textContent = state.revealed
    ? 'Lösung eingeblendet'
    : state.hintsUsed
      ? `${state.hintsUsed} Hinweis${state.hintsUsed > 1 ? 'e' : ''} verwendet`
      : 'Ohne Hinweise gelöst';
  setStatus(`Gelöst in ${fmtTime(state.elapsed)}.`, 'ok');
  save();
}

function startTimer() {
  if (state.running || state.solved) return;
  state.running = true;

