test('zeichnet Brücken passend zur Anzahl', async () => {
  const dom = createFakeDom();
  globalThis.document = dom;
  const { boardToSvgElement } = await import('../js/svg.js');

  const board = buildBoard(
    [
      { id: 0, r: 0, c: 0, num: 2 },
      { id: 1, r: 0, c: 2, num: 2 },
    ],
    3,
    3,
  );
  const single = boardToSvgElement(board, { bridges: new Map([['e0', 1]]) });
  const linesSingle = single.children.flatMap((g) => g.children ?? []).filter((c) => c.tagName === 'line');
  assert.equal(linesSingle.length, 7, '6 Hilfslinien + 1 Brücke');

  const double = boardToSvgElement(board, { bridges: new Map([['e0', 2]]) });
  const linesDouble = double.children.flatMap((g) => g.children ?? []).filter((c) => c.tagName === 'line');
  assert.equal(linesDouble.length, 8, '6 Hilfslinien + 2 Brücken (Doppelbrücke)');
  delete globalThis.document;
});

