    const fire = (t, x, y) => canvas.dispatchEvent(new PointerEvent(t, { clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, isPrimary: true }));
    const ctx = canvas.getContext('2d');
    const dpr = canvas.width / rect.width;

    // Pixel entlang der Diagonalen einer Insel pruefen (oben rechts = rechts oben)
    const sampleDiagonal = (isl) => {
      const c = ctr(isl.r, isl.c);
