input.script:
(async () => {
    const gen = await import('./js/generator.js');
    const brd = await import('./js/board.js');
    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const board = brd.buildBoard(p.islands, p.cols, p.rows);
    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const cell = Math.min(rect.width / p.cols, rect.height / p.rows);
    const ox = rect.left + (rect.width - cell * p.cols) / 2;
    const oy = rect.top + (rect.height - cell * p.rows) / 2;
    const ctr = (r0, c0) => ({ x: ox + (c0 + 0.5) * cell, y: oy + (r0 + 0.5) * cell });
    const ctx = canvas.getContext('2d');
    const dpr = canvas.width / rect.width;

    const sample = (isl) => {
      const c = ctr(isl.r, isl.c);
      const R = cell * 0.33;
      const px = Math.round((c.x - rect.left + R * 0.5) * dpr);
      const py = Math.round((c.y - rect.top - R * 0.5) * dpr);
      const d = ctx.getImageData(px, py, 1, 1).data;
      return d[0] + d[1] + d[2];
    };

    const countStrikes = () => p.islands.filter(i => sample(i) < 400).length;

    // 25 Hinweise -> fast vollstaendige Loesung
    for (let i = 0; i < 25; i++) document.getElementById('hintBtn').click();
    const withHints = countStrikes();

    // Neues Rätsel -> keine durchgestrichenen Inseln
    document.getElementById('newBtn').click();
    const ohne = countStrikes();
    return { inseln: p.islands.length, durchgestrichenNachHinweisen: withHints, durchgestrichenNeu: ohne, bruecken: document.getElementById('bridgeCount').textContent };
  })()

