const tabID = "tab_79632cb9-39d4-4fa9-a463-d96accc5893a";
const r = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const gen = await import('./js/generator.js');
    const brd = await import('./js/board.js');
    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const dpr = canvas.width / rect.width;
    const ctx = canvas.getContext('2d');

    const pruefe = (p) => {
      const cell = Math.min(rect.width / p.cols, rect.height / p.rows);
      const ox = rect.left + (rect.width - cell * p.cols) / 2;
      const oy = rect.top + (rect.height - cell * p.rows) / 2;
      const R = cell * 0.33;
      let strikes = 0;
      for (const isl of p.islands) {
        const x = ox + (isl.c + 0.5) * cell;
        const y = oy + (isl.r + 0.5) * cell;
        // Weiter aussen auf der Diagonalen messen (ausserhalb des Zahlen-Halos)
        const px = Math.round((x - rect.left + R * 0.75) * dpr);
        const py = Math.round((y - rect.top - R * 0.75) * dpr);
        const d = ctx.getImageData(px, py, 1, 1).data;
        if (d[0] + d[1] + d[2] < 450) strikes++;
      }
      return strikes;
    };

    // 1) Frisches Rätsel: keine durchgestrichenen Inseln
    document.getElementById('newBtn').click();
    let seed = document.getElementById('seedInput').value;
    let p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const frisch = pruefe(p);

    // 2) Alle Bruecken per Hinweis setzen
    for (let i = 0; i < 40; i++) document.getElementById('hintBtn').click();
    const voll = pruefe(p);
    return { inseln: p.islands.length, durchgestrichenFrisch: frisch, durchgestrichenVoll: voll, bruecken: document.getElementById('bridgeCount').textContent };
  })()`
});
const cons = await tools.browser.console({ tabID, level: "error", limit: 10 });
return { r: r.value, errors: cons.messages };

