  script: `(async () => {
    const gen = await import('./js/generator.js');
    const brd = await import('./js/board.js');
    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const dpr = canvas.width / rect.width;
    const ctx = canvas.getContext('2d');

    document.getElementById('newBtn').click();
    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const cell = Math.min(rect.width / p.cols, rect.height / p.rows);
    const ox = rect.left + (rect.width - cell * p.cols) / 2;
    const oy = rect.top + (rect.height - cell * p.rows) / 2;
    const R = cell * 0.33;

    const sample = (isl) => {
      const x = ox + (isl.c + 0.5) * cell;
      const y = oy + (isl.r + 0.5) * cell;
      const px = Math.round((x - rect.left + R * 0.8) * dpr);
      const py = Math.round((y - rect.top - R * 0.8) * dpr);
      const d = ctx.getImageData(px, py, 1, 1).data;
      return d[0] + d[1] + d[2];
    };

    const before = p.islands.map(sample);
    for (let i = 0; i < 40; i++) document.getElementById('hintBtn').click();
    const after = p.islands.map(sample);

    const veraendert = before.map((b, i) => after[i] < b - 100).filter(Boolean).length;
    return {
      inseln: p.islands.length,
      dunkelerGeworden: veraendert,
      beispiel: p.islands.slice(0, 4).map((isl, i) => ({ num: isl.num, vorher: before[i], nachher: after[i] })),
    };
  })()`
});
return r.value;

