const tabID = "tab_79632cb9-39d4-4fa9-a463-d96accc5893a";
const r = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const gen = await import('./js/generator.js');
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    const dpr = canvas.width / rect.width;
    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const cell = Math.min(rect.width / p.cols, rect.height / p.rows);
    const ox = rect.left + (rect.width - cell * p.cols) / 2;
    const oy = rect.top + (rect.height - cell * p.rows) / 2;
    const isl = p.islands[0];
    const x = ox + (isl.c + 0.5) * cell;
    const y = oy + (isl.r + 0.5) * cell;
    const probe = (dx, dy) => {
      const px = Math.round((x - rect.left + dx) * dpr);
      const py = Math.round((y - rect.top + dy) * dpr);
      const d = ctx.getImageData(px, py, 1, 1).data;
      return [d[0], d[1], d[2], d[3]];
    };
    return {
      rect: { l: Math.round(rect.left), t: Math.round(rect.top), w: Math.round(rect.width), h: Math.round(rect.height) },
      canvas: { w: canvas.width, h: canvas.height, cssW: canvas.style.width, cssH: canvas.style.height },
      dpr,
      grid: { cols: p.cols, rows: p.rows, cell: Math.round(cell), ox: Math.round(ox), oy: Math.round(oy) },
      insel: { r: isl.r, c: isl.c, x: Math.round(x), y: Math.round(y) },
      pixelMitte: probe(0, 0),
      pixelObenRechts: probe(cell * 0.2, -cell * 0.2),
    };
  })()`
});
return r.value;

