const r = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const gen = await import('./js/generator.js');
    const canvas = document.getElementById('board');
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    const dpr = canvas.width / rect.width;

    // Geometrie exakt wie im Renderer (inkl. Rand für den Rahmen)
    const setup = (p) => {
      const w = Math.floor(rect.width), h = Math.floor(rect.height);
      const margin = Math.max(10, Math.min(w, h) * 0.05);
      const cell = Math.min((w - 2 * margin) / p.cols, (h - 2 * margin) / p.rows);
      const ox = (w - cell * p.cols) / 2;
      const oy = (h - cell * p.rows) / 2;
      const R = cell * 0.33;
      return (isl) => {
        const x = ox + (isl.c + 0.5) * cell;
        const y = oy + (isl.r + 0.5) * cell;
        const px = Math.round((x + R * 0.72) * dpr);
        const py = Math.round((y - R * 0.72) * dpr);
        const d = ctx.getImageData(px, py, 1, 1).data;
        return d[0] + d[1] + d[2];
      };
    };

    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const sample = setup(p);

    const before = p.islands.map(sample);
    for (let i = 0; i < 40; i++) document.getElementById('hintBtn').click();
    const after = p.islands.map(sample);

    const veraendert = before.map((b, i) => after[i] < b - 80).filter(Boolean).length;
    return {
      inseln: p.islands.length,
      durchgestrichen: veraendert,
      beispiel: p.islands.slice(0, 6).map((isl, i) => ({ num: isl.num, vorher: before[i], nachher: after[i] })),
    };
  })()`
});
const cons = await tools.browser.console({ tabID, level: "error", limit: 10 });
return { r: r.value, errors: cons.messages };

