/**
 * Anzahl der Möglichkeiten, die restlichen Brücken einer Insel zu verteilen.
 * Wenige Möglichkeiten = die Insel ist stark eingeschränkt und eignet sich
 * als Verzweigungspunkt (klassische CSP-Heuristik "least constrained value"
 * in der Umkehrung).
 */
waysFor(island, dom) {
  const edges = this.incident[island];
  if (!edges.length) return 1;
  let need = island.num;
  // Verteilung der noch offenen Summe zählen (kleine DP über die Kanten)
  let counts = new Map([[0, 1]]);
  for (const e of edges) {
    const d = dom[e];
    const next = new Map();
    for (const [sum, count] of counts) {
      for (let v = 0; v <= 2; v++) {
        if (!(d & (1 << v))) continue;
        const s = sum + v;
        if (s > need) break;
        next.set(s, (next.get(s) ?? 0) + count);
      }
    }
    counts = next;
    if (!counts.size) return 0;
  }
  return counts.get(need) ?? 0;
}

/**
 * Sucht bis zu `limit` Lösungen.
 * @param {number} limit
 * @returns {number[][]} Array von Brückenzahlen pro Kante
 */
findSolutions(limit = 2) {
  const { edges, m, incident, crossings, islands } = this;
  const solutions = [];
  this.nodes = 0;

  if (islands.length === 0) return solutions;

