input.newString:
const search = (d) => {
  if (solutions.length >= limit) return;
  this.nodes++;

  // Verzweigung: Kante an der am stärksten eingeschränkten Insel wählen.
  // Das ist wesentlich schneller als "kleinste Domäne" bei dichten Brettern.
  let best = -1;
  let bestScore = Infinity;
  for (let i = 0; i < islands.length; i++) {
    const ways = this.waysFor(islands[i], d);
    if (ways === 0) return; // unmöglich
    if (ways > 64) continue; // zu unscharf
    for (const e of incident[i]) {
      const size = popcount(d[e]);
      if (size <= 1) continue;
      // Wenige Möglichkeiten sind besser, danach die kleinere Domäne
      const score = ways * 100 + size;
      if (score < bestScore) {
        bestScore = score;
        best = e;
      }
    }
  }

  if (best === -1) {
    // Nichts eingeschränkt -> beliebige Kante mit offener Domäne
    for (let e = 0; e < m; e++) {
      if (popcount(d[e]) > 1) {
        best = e;
        break;
      }
    }
  }

  if (best === -1) {
    // Alle Kanten sind festgelegt -> Kandidat prüfen
    const counts = new Int8Array(m);
    for (let e = 0; e < m; e++) counts[e] = valOf(d[e]);
    if (isCompleteSolution(counts)) solutions.push(Array.from(counts));
    return;
  }

  const cur = d[best];
  // Reihenfolge: erst viele, dann mittlere, dann keine Brücken.
  for (const v of [2, 1, 0]) {
    if (!(cur & (1 << v))) continue;
    const nd = Int8Array.from(d);
    nd[best] = 1 << v;
    if (this.propagate(nd) && this.potentialConnected(nd)) search(nd);
    if (solutions.length >= limit) return;
  }
};

