import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

// Welche Mutation reduziert die Anzahl Loesungen am besten?
const stats = {};
for (let i=0;i<10;i++){
  const rng = new RNG("M|"+i);
  const sol = internals.growSolution(rng, 100, 20, 18, 0, 2);
  if (!sol) continue;
  const board = internals.boardOf(sol, internals.numbersOf(sol));
  const intended = internals.countsOf(board, sol);
  const sols = findSolutions(board, 3);
  if (sols.length !== 2) continue;
  const alt = sols[1];
  const diffs = [];
  for (let e=0;e<board.edges.length;e++) if (alt[e]!==intended[e]) diffs.push(e);
  for (const e of diffs.slice(0,6)) {
    const ed = board.edges[e];
    for (const w of [0,1,2]) {
      if (w === intended[e]) continue;
      const cand = internals.withEdge(sol, ed.a, ed.b, w);
      if (!cand || !internals.validateSolution(cand)) { (stats[`${intended[e]}->${w} ungueltig`] ||= []).push("x"); continue; }
      const b2 = internals.boardOf(cand, internals.numbersOf(cand));
      const s2 = findSolutions(b2, 6);
      const key = `${intended[e]}->${w}`;
      (stats[key] ||= []).push(s2.length);
    }
  }
}
for (const [k,v] of Object.entries(stats)) {
  const valid = v.filter(x=>x!=="x");
  if (!valid.length) { console.log(`${k}: alle ungueltig`); continue; }
  const avg = valid.reduce((a,b)=>a+b,0)/valid.length;
  const besser = valid.filter(x=>x<=2).length;
  console.log(`${k}: Loesungen=[${v.join(",")}] avg=${avg.toFixed(2)} verbessert=${besser}/${valid.length}`);
}
