describe('generatePuzzle – Heft-Format (DIN A6)', () => {
  test('erzeugt Rätsel mit etwa 100 Inseln', () => {
    for (let i = 0; i < 3; i++) {
      const puzzle = generatePuzzle({
        difficulty: 'medium',
