  test('auch das Heft-Format ist eindeutig lösbar', () => {
    for (let i = 0; i < 3; i++) {
      const puzzle = generatePuzzle({
        difficulty: 'hard',
        seed: `HEFT-EINDEUTIG-${i}`,
        islands: 100,
        format: BOOKLET_FORMAT,
        keep: 1,
      });
      const board = buildBoard(
        puzzle.islands.map((isl) => ({ id: isl.id, r: isl.r, c: isl.c, num: isl.num })),
        puzzle.cols,
        puzzle.rows,
