    const puzzle = generatePuzzle({
      difficulty: 'medium',
      seed: 'HEFT-GROESSE',
      islands: 100,
      format: BOOKLET_FORMAT,
      keep: 1,
    });
    // Das Raster muss so kompakt sein, dass die Inseln auf A6 passen
    assert.ok(puzzle.cols <= 20 && puzzle.rows <= 20, 'Raster zu gross für A6');
