@'
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

// Welche Mutation reduziert die Loesungszahl bei Brettern MIT Doppelbruecken?
const stats = {};
for (let i=0;i<6;i++){
  const rng = new RNG("DBL|100|"+i);
  const sol = internals.growSolution(rng, 100, 18, 18, 0.08, 2);
  if (!sol) continue;
  const board = internals.boardOf(sol, internals.numbersOf(sol));
  const sols = findSolutions(board, 3);
  if (sols.length < 2) continue;
  const start = sols.length;
  const used = new Set(sol.edges.map(e=>`${Math.min(e.a,e.b)}-${Math.max(e.a,e.b)}`));

  for (const e of board.edges) {
    const k = `${Math.min(e.a,e.b)}-${Math.max(e.a,e.b)}`;
    if (!used.has(k)) continue;
    const cur = sol.edges.find(x=>`${Math.min(x.a,x.b)}-${Math.max(x.a,x.b)}`===k);
    for (const w of [1,2]) {
      if (w === cur.w) continue;
      const cand = internals.withEdge(sol, e.a, e.b, w);
      if (!cand || !internals.validateSolution(cand)) continue;
      const b2 = internals.boardOf(cand, internals.numbersOf(cand));
      const s2 = findSolutions(b2, 4);
      const key = `${cur.w}->${w}`;
      (stats[key] ||= []).push(s2.length);
    }
  }
  console.log(`#${i}: Start=${start} Loesungen`);
}
console.log("");
for (const [k,v] of Object.entries(stats)) {
  const avg = v.reduce((a,b)=>a+b,0)/v.length;
  console.log(`Mutation ${k}: danach=[${v.join(",")}] avg=${avg.toFixed(2)} besser=${v.filter(x=>x<=2).length}/${v.length}`);
}
