import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

for (const dbl of [0, 0.03, 0.05, 0.08, 0.12, 0.2]) {
  let quote=0, versuche=0, tSum=0, doppel=0, N=10;
  for(let i=0;i<N;i++){
    const rng=new RNG("SC|"+dbl+i);
    const t0=Date.now();
    for(let v=0; v<40; v++){
      versuche++;
      const sol=internals.growSolution(rng,100,18,18,dbl,2);
      if(!sol||!internals.validateSolution(sol)) continue;
      const b=internals.boardOf(sol,internals.numbersOf(sol));
      if(findSolutions(b,2).length===1){ quote++; doppel += sol.edges.filter(e=>e.w===2).length; break; }
    }
    tSum+=Date.now()-t0;
  }
  console.log(`doppelt=${String(dbl).padEnd(5)}: quote=${(quote/N*100).toFixed(0)}% versuche/erfolg=${(versuche/Math.max(1,quote)).toFixed(1)} zeit=${(tSum/N).toFixed(0)}ms doppelbruecken=${(doppel/Math.max(1,quote)).toFixed(1)}`);
}
