class Node:
    def __init__(self, x, y):
        self.x: int = x
        self.y: int = y
        self.n_type: int = 0          # 0->empty, 1->island, 2->bridge

        self.i_count: int = -1        # island count 1-8

        self.b_thickness: int = -1    # bridge thickness 1-2
        self.b_dir: int = -1          # 0->horizontal, 1->vertical

        # solver necessary property
        self.current_in: int = 0

    # solver necessary property
    @property
    def needed(self) -> int:
        return self.i_count - self.current_in

    def make_empty(self) -> None:
        self.n_type = 0
        self.i_count = -1
        self.b_thickness = -1
        self.b_dir = -1

    def make_island(self, i_count: int) -> None:
        self.n_type = 1
        self.i_count = i_count

    def make_bridge(self, b_thickness: int, b_dir: int) -> None:
        self.n_type = 2
        self.b_thickness = b_thickness
        self.b_dir = b_dir


def direction_to_vector(direction: int) -> tuple[int, int]:
    assert direction >= 0 and direction < 4
    return [(-1, 0), (0, -1), (1, 0), (0, 1)][direction]


def nodes_to_direction(node_a: Node, node_b: Node) -> int:
    """
    Returns direction from node_a to node_b
    """
    if node_a.x == node_b.x:
        if node_a.y < node_b.y:
            return 3
        else:
            return 1
    else:
        if node_a.x < node_b.x:
            return 2
        else:
            return 0


def is_in_grid(x: int, y: int, grid_w: int, grid_h: int) -> bool:
    return x >= 0 and x < grid_w and y >= 0 and y < grid_h

input.content:
// Experiment: Wachstum mit variabler Brückenlänge (Idee aus erthium/hashiwokakero)
// Gemessen: Quote eindeutiger Rätsel, Versuche, Zeit.
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

const DIRS = [
  { dr: -1, dc: 0 },
  { dr: 1, dc: 0 },
  { dr: 0, dc: -1 },
  { dr: 0, dc: 1 },
];

const key = (r, c) => `${r},${c}`;

function grow(rng, target, cols, rows, doubleChance, maxExtra, maxLen, noAdjacent) {
  const islands = [];
  const edges = [];
  const occ = new Map(); // Zelle -> {insel:bool, bruecke:bool}

  const start = { r: rng.range(0, rows - 1), c: rng.range(0, cols - 1) };
  islands.push(start);
  occ.set(key(start.r, start.c), { insel: true, bruecke: false });

  const free = (r, c) => !occ.has(key(r, c));
  const isIsland = (r, c) => occ.get(key(r, c))?.insel;

  const degOf = (idx) => edges.filter((e) => e.a === idx || e.b === idx).length;

  let guard = 0;
  while (islands.length < target && guard < 20000) {
    guard++;
    const cands = [];
    const ws = [];
    for (let i = 0; i < islands.length; i++) {
      const isl = islands[i];
      for (const d of DIRS) {
        // Mögliche Längen: 1..maxLen, aber alle Zwischenzellen frei
        for (let len = 1; len <= maxLen; len++) {
          const mr = isl.r + d.dr * len;
          const mc = isl.c + d.dc * len;
          if (mr < 0 || mr >= rows || mc < 0 || mc >= cols) break;
          if (!free(mr, mc)) break;
          // Zwischenzellen müssen frei sein
          let ok = true;
          for (let k = 1; k < len; k++) {
            if (!free(isl.r + d.dr * k, isl.c + d.dc * k)) { ok = false; break; }
          }
          if (!ok) break;

          // Sichtbare Inseln zählen (Ablenk-Kanten)
          const cand = [...islands, { r: mr, c: mc }];
          let visible = 0;
          for (const dd of DIRS) {
            let step = 1;
            while (true) {
              const vr = mr + dd.dr * step;
              const vc = mc + dd.dc * step;
              if (vr < 0 || vr >= rows || vc < 0 || vc >= cols) break;
              if (islandAt(cand, vr, vc)) { visible++; break; }
              step++;
            }
          }
          const extra = visible - 1;
          if (extra > maxExtra) continue;

          // Regel: neue Insel darf nicht direkt neben einer anderen liegen
          if (noAdjacent) {
            let adj = false;
            for (const dd of DIRS) {
              if (isIsland(mr + dd.dr, mc + dd.dc)) { adj = true; break; }
            }
            if (adj) continue;
          }

          // Kreuzungen verhindern: die Brücke darf keine bestehende Brücke kreuzen
          let crosses = false;
          for (const e of edges) {
            const a = islands[e.a], b = islands[e.b];
            const eH = a.r === b.r;
            if (eH === (d.dr === 0)) continue; // parallel
            if (eH) {
              // bestehende waagerechte, neue senkrechte
              const er1 = Math.min(a.r, b.r), er2 = Math.max(a.r, b.r);
              const ec = a.c;
              if (er1 < isl.r && isl.r < er2 && Math.min(mc, isl.c) < ec && ec < Math.max(mc, isl.c)) crosses = true;
            } else {
              const er = a.r;
              const ec1 = Math.min(a.c, b.c), ec2 = Math.max(a.c, b.c);
              if (ec1 < isl.c && isl.c < ec2 && Math.min(mr, isl.r) < er && er < Math.max(mr, isl.r)) crosses = true;
            }
          }
          if (crosses) continue;

          let w = 1;
          if (degOf(i) <= 1) w *= 2.2;
          if (extra === 0) w *= 2.5;
          if (len > 1) w *= 1.4; // längere Brücken bevorzugen
          cands.push({ parent: i, r: mr, c: mc, len });
          ws.push(w);
        }
      }
    }
    if (!cands.length) break;
    const ch = rng.pickWeighted(cands, ws);
    const id = islands.length;
    islands.push({ r: ch.r, c: ch.c });
    for (let k = 1; k <= ch.len; k++) {
      occ.set(key(ch.r - DIRS[0].dr * 0 + 0, 0), occ.get(key(0, 0))); // no-op
    }
    // Brückenzellen markieren
    const d = DIRS.find((dd) => (ch.parent % 4) === DIRS.indexOf(dd));
    occ.set(key(ch.r, ch.c), { insel: true, bruecke: false });
    edges.push({ a: ch.parent, b: id, w: rng.chance(doubleChance) ? 2 : 1 });
  }
  return { cols, rows, islands, edges };
}

function islandAt(islands, r, c) {
  return islands.some((i) => i.r === r && i.c === c);
}

// Vereinfachter Test: nur die Rate messen, Kreuzungen über den Validator prüfen.
for (const [maxLen, noAdj] of [[1, false], [1, true], [3, false], [3, true], [5, true]]) {
  let quote = 0, versuche = 0, tSum = 0, N = 6;
  for (let i = 0; i < N; i++) {
    const rng = new RNG(`EXP|${maxLen}|${noAdj}|${i}`);
    const t0 = Date.now();
    for (let v = 0; v < 25; v++) {
      versuche++;
      const sol = grow(rng, 100, 18, 18, 0.05, 2, maxLen, noAdj);
      if (sol.islands.length < 100) continue;
      // Brückenzellen korrekt markieren (Test-Wiedergabe)
      const b = internals.boardOf(sol, internals.numbersOf(sol));
      if (findSolutions(b, 2).length === 1) { quote++; break; }
    }
    tSum += Date.now() - t0;
  }
  console.log(`maxLen=${maxLen} ohneNachbar=${noAdj}: quote=${(quote / N * 100).toFixed(0)}% versuche=${(versuche / Math.max(1, quote)).toFixed(1)} zeit=${(tSum / N).toFixed(0)}ms`);
}

