      if (liesOnBridge(islands, edges, kr, kc)) { blocked = true; break; }
    }
    if (blocked) break;  // a longer bridge would also pass through this cell
    if (dist === maxLen && ...) 
    // the new island's cell (dist) must not lie on an existing bridge
    if (liesOnBridge(islands, edges, nr, nc)) break;
    if (crossesExisting(islands, edges, isl.r, isl.c, nr, nc)) continue;
    ...
  }
