// Vergleich: Wachstum mit fester Brückenlänge 1-2 (bisher) gegen
// variable Brückenlängen (Idee aus erthium/hashiwokakero).
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

console.log("Format: 100 Inseln, 18x18, maxExtra=2");
console.log("maxLen  keinNachbar  quote  versuche  zeit     doppel  abl.kanten");
for (const maxLen of [2, 3, 4, 6]) {
  for (const noAdj of [false, true]) {
    let quote = 0, versuche = 0, tSum = 0, doppel = 0, decoys = 0, N = 8;
    for (let i = 0; i < N; i++) {
      const rng = new RNG(`CMP|${maxLen}|${noAdj}|${i}`);
      const t0 = Date.now();
      for (let v = 0; v < 30; v++) {
        versuche++;
        const sol = internals.growSolution(rng, 100, 18, 18, 0.05, 2, maxLen, noAdj);
        if (!sol || sol.islands.length < 100) continue;
        if (!internals.validateSolution(sol)) continue;
        const b = internals.boardOf(sol, internals.numbersOf(sol));
        if (findSolutions(b, 2).length === 1) {
          quote++;
          doppel += sol.edges.filter((e) => e.w === 2).length;
          decoys += b.edges.length - sol.edges.length;
          break;
        }
      }
      tSum += Date.now() - t0;
    }
    console.log(
      `${String(maxLen).padEnd(7)} ${String(noAdj).padEnd(13)} ${String((quote / N * 100).toFixed(0)).padStart(3)}%  ` +
      `${(versuche / Math.max(1, quote)).toFixed(1).padStart(7)}  ${(tSum / N).toFixed(0).padStart(5)}ms  ` +
      `${(doppel / Math.max(1, quote)).toFixed(1).padStart(5)}  ${(decoys / Math.max(1, quote)).toFixed(1).padStart(8)}`,
    );
  }
}

// Sweep: variable Brückenlänge x Doppelbrücken-Anteil x Inselzahl
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

for (const [inseln, cols, rows] of [[40, 12, 12], [100, 18, 18]]) {
  console.log(`\n=== ${inseln} Inseln (${cols}x${rows}) ===`);
  console.log("maxLen  doppelt  quote  versuche  zeit     doppelbruecken");
  for (const maxLen of [2, 3, 4, 5, 8]) {
    for (const dbl of [0.05, 0.12, 0.25]) {
      let quote = 0, versuche = 0, tSum = 0, doppel = 0, N = 6;
      for (let i = 0; i < N; i++) {
        const rng = new RNG(`SW|${inseln}|${maxLen}|${dbl}|${i}`);
        const t0 = Date.now();
        for (let v = 0; v < 40; v++) {
          versuche++;
          const sol = internals.growSolution(rng, inseln, cols, rows, dbl, 2, maxLen, false);
          if (!sol || sol.islands.length < inseln) continue;
          if (!internals.validateSolution(sol)) continue;
          const b = internals.boardOf(sol, internals.numbersOf(sol));
          if (findSolutions(b, 2).length === 1) {
            quote++;
            doppel += sol.edges.filter((e) => e.w === 2).length;
            break;
          }
        }
        tSum += Date.now() - t0;
      }
      console.log(
        `${String(maxLen).padEnd(7)} ${String(dbl).padEnd(8)} ${String((quote / N * 100).toFixed(0)).padStart(3)}%  ` +
        `${(versuche / Math.max(1, quote)).toFixed(1).padStart(7)}  ${(tSum / N).toFixed(0).padStart(5)}ms  ` +
        `${(doppel / Math.max(1, quote)).toFixed(1).padStart(10)}`,
      );
    }
  }
}

