// Erzeugt je ein Beispielrätsel als SVG, um die Optik zu beurteilen.
import { writeFileSync } from "node:fs";
import { generatePuzzle, DIFFICULTIES, BOOKLET_FORMAT } from "./js/generator.js";
import { buildBoard } from "./js/board.js";

const escape = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");

function svgFor(puzzle, file) {
  const board = buildBoard(
    puzzle.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
    puzzle.cols,
    puzzle.rows,
  );
  const cell = 34;
  const pad = 10;
  const w = puzzle.cols * cell + pad * 2;
  const h = puzzle.rows * cell + pad * 2;
  const sol = new Map(board.edges.map((e, i) => [e.id, puzzle.solution[i]]));
  const parts = [];
  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">`);
  parts.push(`<rect width="${w}" height="${h}" fill="#ffffff"/>`);
  parts.push(`<g stroke="#1f2937" stroke-width="0.16" stroke-opacity="0.16" stroke-dasharray="1 4">`);
  for (let c = 0; c <= puzzle.cols; c++) {
    parts.push(`<line x1="${pad + c * cell}" y1="${pad}" x2="${pad + c * cell}" y2="${pad + puzzle.rows * cell}"/>`);
  }
  for (let r = 0; r <= puzzle.rows; r++) {
    parts.push(`<line x1="${pad}" y1="${pad + r * cell}" x2="${pad + puzzle.cols * cell}" y2="${pad + r * cell}"/>`);
  }
  parts.push(`</g>`);
  parts.push(`<g stroke="#1f2937" stroke-width="3" stroke-linecap="round">`);
  for (const edge of board.edges) {
    const n = sol.get(edge.id) ?? 0;
    if (!n) continue;
    const a = board.islands[edge.a];
    const b = board.islands[edge.b];
    const ax = pad + (a.c + 0.5) * cell, ay = pad + (a.r + 0.5) * cell;
    const bx = pad + (b.c + 0.5) * cell, by = pad + (b.r + 0.5) * cell;
    const offs = n >= 2 ? [-4, 4] : [0];
    for (const o of offs) {
      if (edge.dir === "h") parts.push(`<line x1="${ax}" y1="${ay + o}" x2="${bx}" y2="${by + o}"/>`);
      else parts.push(`<line x1="${ax + o}" y1="${ay}" x2="${bx + o}" y2="${by}"/>`);
    }
  }
  parts.push(`</g>`);
  for (const isl of board.islands) {
    const cx = pad + (isl.c + 0.5) * cell, cy = pad + (isl.r + 0.5) * cell;
    parts.push(`<circle cx="${cx}" cy="${cy}" r="10" fill="#fff" stroke="#111" stroke-width="2"/>`);
    parts.push(`<text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central" font-size="13" font-weight="700" font-family="sans-serif" fill="#000">${isl.num}</text>`);
  }
  parts.push(`</svg>`);
  writeFileSync(file, parts.join("\n"));
  console.log(`${file}: ${puzzle.islands.length} Inseln, ${puzzle.doubles} Doppelbrücken`);
}

