// Vergleich der Brückenstruktur: bisher (nur 1-2 Felder) vs. variabel
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

function stats(sol) {
  const len = {};
  let cross = 0;
  for (const e of sol.edges) {
    const a = sol.islands[e.a], b = sol.islands[e.b];
    const d = Math.abs(a.r - b.r) + Math.abs(a.c - b.c);
    len[d] = (len[d] || 0) + 1;
  }
  return len;
}

console.log("Brückenlängen (Anzahl Brücken je Länge in Feldern)");
console.log("variante      inseln  quote  len1  len2  len3  len4+  doppel");
for (const [name, maxLen] of [["nur 1-2 Felder", 2], ["variabel bis 4", 4], ["variabel bis 6", 6]]) {
  let quote = 0, n = 0, doppel = 0, agg = {};
  const N = 8;
  for (let i = 0; i < N; i++) {
    const rng = new RNG(`ST|${maxLen}|${i}`);
    for (let v = 0; v < 40; v++) {
      const sol = internals.growSolution(rng, 40, 12, 12, 0.18, 2, maxLen, false);
      if (!sol || sol.islands.length < 40) continue;
      if (!internals.validateSolution(sol)) continue;
      const b = internals.boardOf(sol, internals.numbersOf(sol));
      if (findSolutions(b, 2).length !== 1) continue;
      quote++;
      n = sol.islands.length;
      doppel += sol.edges.filter((e) => e.w === 2).length;
      for (const [k, v2] of Object.entries(stats(sol))) agg[k] = (agg[k] || 0) + v2;
      break;
    }
  }
  const per = (k) => ((agg[k] || 0) / Math.max(1, quote)).toFixed(1).padStart(4);
  const len4 = ((agg["4"] || 0) + (agg["5"] || 0) + (agg["6"] || 0)) / Math.max(1, quote);
  console.log(
    `${name.padEnd(14)} ${String(n).padStart(4)}  ${String((quote / N * 100).toFixed(0)).padStart(3)}%  ` +
    `${per(1)} ${per(2)} ${per(3)} ${len4.toFixed(1).padStart(5)}  ${(doppel / Math.max(1, quote)).toFixed(1).padStart(5)}`,
  );
}

// End-to-End-Benchmark der Spielstufen mit der neuen Konfiguration
import { generatePuzzle, BOOKLET_FORMAT } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { findSolutions } from "./js/solver.js";

console.log("Stufe    ok    inseln   doppel  zeit avg   max");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  let ok = 0, tSum = 0, tMax = 0, nSum = 0, dSum = 0, N = 15;
  for (let i = 0; i < N; i++) {
    const t0 = Date.now();
    const p = generatePuzzle({ difficulty: diff, seed: `NEU-${diff}-${i}` });
    const dt = Date.now() - t0;
    tSum += dt; tMax = Math.max(tMax, dt);
    const b = buildBoard(p.islands, p.cols, p.rows);
    const s = findSolutions(b, 2);
    if (s.length === 1 && JSON.stringify(s[0]) === JSON.stringify(p.solution)) ok++;
    nSum += p.islands.length; dSum += p.doubles;
  }
  console.log(
    `${diff.padEnd(8)} ${ok}/${N}  ${(nSum / N).toFixed(0).padStart(5)}  ${(dSum / N).toFixed(1).padStart(5)}  ` +
    `${(tSum / N).toFixed(0).padStart(6)}ms ${String(tMax).padStart(6)}ms`,
  );
}

// Gezielte Messung für das Heft-Format (100 Inseln)
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

console.log("maxLen  doppelt  quote  versuche  zeit      doppelbruecken");
for (const maxLen of [3, 4, 6]) {
  for (const dbl of [0.05, 0.12, 0.2]) {
    let quote = 0, versuche = 0, tSum = 0, doppel = 0, N = 5;
    for (let i = 0; i < N; i++) {
      const rng = new RNG(`HF|${maxLen}|${dbl}|${i}`);
      const t0 = Date.now();
      for (let v = 0; v < 40; v++) {
        versuche++;
        const sol = internals.growSolution(rng, 100, 18, 18, dbl, 2, maxLen, false);
        if (!sol || sol.islands.length < 100) continue;
        if (!internals.validateSolution(sol)) continue;
        const b = internals.boardOf(sol, internals.numbersOf(sol));
        if (findSolutions(b, 2).length === 1) {
          quote++;
          doppel += sol.edges.filter((e) => e.w === 2).length;
          break;
        }
      }
      tSum += Date.now() - t0;
    }
    console.log(
      `${String(maxLen).padEnd(7)} ${String(dbl).padEnd(8)} ${String((quote / N * 100).toFixed(0)).padStart(3)}%  ` +
      `${(versuche / Math.max(1, quote)).toFixed(1).padStart(7)}  ${(tSum / N / 1000).toFixed(1).padStart(5)}s  ` +
      `${(doppel / Math.max(1, quote)).toFixed(1).padStart(10)}`,
    );
  }
}

