// Misst, ob der Solver-Aufwand (Verzweigungsschritte) die Stufen besser
// trennt als die reine Inselzahl – und ob er innerhalb einer Stufe
// differenziert.
import { generatePuzzle, DIFFICULTIES } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { Solver, propagationStatus } from "./js/solver.js";

function messen(puzzle) {
  const board = buildBoard(
    puzzle.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
    puzzle.cols,
    puzzle.rows,
  );
  const s = new Solver(board);
  const t0 = Date.now();
  const sols = s.findSolutions(2);
  const ms = Date.now() - t0;
  const prop = propagationStatus(board);
  return {
    inseln: puzzle.islands.length,
    doppel: puzzle.doubles,
    knoten: s.nodes,
    regel: s.ruleSteps,
    ms,
    bestimmt: prop.determined,
    kanten: board.edges.length,
    loesungen: sols.length,
  };
}

console.log("Stufe     n    doppel  knoten   regel   bestimmt  anteil   ms");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  const rows = [];
  for (let i = 0; i < 10; i++) {
    const p = generatePuzzle({ difficulty: diff, seed: `DIFF-${diff}-${i}` });
    rows.push(messen(p));
  }
  const avg = (k) => (rows.reduce((s, r) => s + r[k], 0) / rows.length).toFixed(1);
  const anteil = (rows.reduce((s, r) => s + r.bestimmt / r.kanten, 0) / rows.length * 100).toFixed(1);
  console.log(
    `${diff.padEnd(9)} ${avg("inseln").padStart(3)}  ${avg("doppel").padStart(5)}  ` +
    `${avg("knoten").padStart(7)}  ${avg("regel").padStart(6)}  ` +
    `${avg("bestimmt").padStart(8)}  ${anteil.padStart(5)}%  ${avg("ms").padStart(5)}`,
  );
  // Streuung der Knoten innerhalb der Stufe
  const k = rows.map((r) => r.knoten).sort((a, b) => a - b);
  console.log(`          Knoten: min=${k[0]} median=${k[Math.floor(k.length / 2)]} max=${k[k.length - 1]}`);
}

// Korrelation Inselzahl <-> Solver-Aufwand
const alle = [];
for (const diff of ["easy", "medium", "hard", "expert"]) {
  for (let i = 0; i < 8; i++) {
    const p = generatePuzzle({ difficulty: diff, seed: `KORR-${diff}-${i}` });
    alle.push(messen(p));
  }
}
const n = alle.length;
const mx = alle.reduce((s, r) => s + r.inseln, 0) / n;
const my = alle.reduce((s, r) => s + r.knoten, 0) / n;
let num = 0, den = 0;
for (const r of alle) {
  num += (r.inseln - mx) * (r.knoten - my);
  den += (r.inseln - mx) ** 2;
}
const r = num / Math.sqrt(den * alle.reduce((s, x) => s + (x.knoten - my) ** 2, 0));
console.log(`\nKorrelation Inselzahl <-> Solver-Knoten: r = ${r.toFixed(3)}`);

/**
 * Schwierigkeitsmessung für Hashi-Rätsel.
 *
 * Angelehnt an die Idee des Projekts
 * https://github.com/erthium/hashiwokakero (GPL-3.0): die Schwierigkeit
 * ergibt sich aus dem *Solver-Aufwand* plus wenigen Strukturmetriken,
 * normiert gegen Referenzbereiche je Puzzle-Grösse. Die Umsetzung hier ist
 * eigenständig in JavaScript; das Projekt steht unter MIT.
 *
 * Anpassungen gegenüber dem Vorbild:
 *   - Statt einer mitgelieferten Kalibrierdatei je Geometrie wird nach
 *     Inselzahl-Bündeln normiert. Das Brett wird auf seinen kleinsten
 *     umschliessenden Rechteck beschnitten, die Geometrie wechselt also
 *     ständig – ein Bündel nach Inselzahl bleibt dagegen stabil.
 *   - Die Metrik "Inseln unter 7" entfällt: in diesem Projekt liegen die
 *     Inselzahlen fast immer zwischen 1 und 5, die Metrik hat also keine
 *     Unterscheidungskraft.
 *   - Statt der absoluten Regelschrittzahl zählt der *Anteil* der rein
 *     logisch bestimmbaren Kanten – er ist unabhängig von der Brettgrösse.
 */

/** Metriken, die in die Bewertung eingehen. */
export const METRICS = ['nodes', 'logicShare', 'avgNumber', 'density'];

/** Gewichte der Metriken (Summe = 1). */
export const WEIGHTS = {
  nodes: 0.5, // Verzweigungsschritte des Solvers – die eigentliche Härte
  logicShare: 0.25, // Anteil der allein durch Logik certain Kanten
  avgNumber: 0.15, // mittlere Inselzahl
  density: 0.1, // Inseldichte
};

/** Grenzen der Inselzahl-Bündel für die Normierung. */
export const BUCKETS = [
  { id: '10-19', min: 10, max: 19 },
  { id: '20-29', min: 20, max: 29 },
  { id: '30-39', min: 30, max: 39 },
  { id: '40-59', min: 40, max: 59 },
  { id: '60-79', min: 60, max: 79 },
  { id: '80-120', min: 80, max: 120 },
];

/** Welches Bündel gehört zu einer bestimmten Inselzahl? */
export function bucketFor(islandCount) {
  for (const bucket of BUCKETS) {
    if (islandCount >= bucket.min && islandCount <= bucket.max) return bucket.id;
  }
  return islandCount < BUCKETS[0].min ? BUCKETS[0].id : BUCKETS[BUCKETS.length - 1].id;
}

/**
 * Erhbt die Rohmetriken eines Rätsels.
 *
 * @param {object} board      Brettmodell
 * @param {object} solver     Solver, der das Brett bereits gelöst hat
 * @param {number} ruleSteps  Propagationsdurchläufe des Solvers
 */
export function measure(board, solver, ruleSteps = 0) {
  const islands = board.islands;
  const count = Math.max(1, islands.length);
  const total = islands.reduce((sum, i) => sum + i.num, 0);
  const determined = solver.propagationStatus().determined;
  return {
    nodes: solver.nodes,
    ruleSteps,
    logicShare: board.edges.length ? determined / board.edges.length : 1,
    avgNumber: total / count,
    density: islands.length / (board.cols * board.rows),
  };
}

/** Linear auf [0, 1] normieren undklemmen. */
function normalise(value, lo, hi) {
  if (hi === lo) return 0;
  const raw = (value - lo) / (hi - lo);
  return raw < 0 ? 0 : raw > 1 ? 1 : raw;
}

/**
 * Berechnet den Schwierigkeitsgrad aus den Metriken und den
 * Referenzbereichen eines Bündels.
 *
 * @param {object} metrics  Rohmetriken
 * @param {object} bounds   Referenzbereiche: { metric: [lo, hi] }
 * @returns {number} 0 (sehr leicht) bis 1 (sehr schwer)
 */
export function score(metrics, bounds) {
  if (!bounds) return 0.5;
  let score = 0;
  for (const metric of METRICS) {
    const range = bounds[metric];
    if (!range) continue;
    let value = normalise(metrics[metric], range[0], range[1]);
    // Der Logikanteil ist invertiert: viel Logik = leicht.
    if (metric === 'logicShare') value = 1 - value;
    score += value * WEIGHTS[metric];
  }
  return Math.min(1, Math.max(0, score));
}

/** Textuelle Einordnung des Schwierigkeitsgrads. */
export function label(value) {
  if (value < 0.2) return 'sehr leicht';
  if (value < 0.4) return 'leicht';
  if (value < 0.6) return 'mittel';
  if (value < 0.8) return 'schwer';
  return 'sehr schwer';
}

/**
 * Erzeugt die Referenzbereiche für die Schwierigkeitsmessung.
 *
 *   npm run calibrate
 *
 * Für jedes Inselzahl-Bündel werden einige hundert Rätsel erzeugt und
 * gelöst. Aus den Verteilungen der Metriken werden die 5- und
 * 95-Perzentile berechnet – sie bilden die Normierungsgrundlage.
 *
 * Das Ergebnis landet in js/data/difficulty.json und wird von
 * js/difficulty.js gelesen. Nach jeder Änderung am Generator sollte die
 * Kalibrierung neu laufen.
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { generatePuzzle, DIFFICULTIES, BOOKLET_FORMAT } from '../js/generator.js';
import { buildBoard } from '../js/board.js';
import { Solver } from '../js/solver.js';
import { BUCKETS, METRICS, measure, bucketFor } from '../js/difficulty.js';

const here = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(here, '..', 'js', 'data', 'difficulty.json');

/** Zielgrössen der Stichprobe je Bündel. */
const SAMPLES = 160;

/** Rätselgrössen, die je Bündel erzeugt werden. */
const SIZES = {
  '10-19': [12, 16],
  '20-29': [20, 26],
  '30-39': [30, 38],
  '40-59': [44, 56],
  '60-79': [60, 75],
  '80-120': [85, 100],
};

function percentile(sorted, p) {
  if (!sorted.length) return 0;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

const samples = new Map();

for (const bucket of BUCKETS) {
  const [min, max] = SIZES[bucket.id] ?? [bucket.min, bucket.max];
  const collected = [];
  let levelIndex = 0;

  while (collected.length < SAMPLES) {
    const level = DIFFICULTY_IDS[levelIndex % DIFFICULTY_IDS.length];
    levelIndex++;
    const cfg = DIFFICULTIES[level];
    const islands = min + (collected.length % (max - min + 1));
    const useBooklet = islands > 60;
    const puzzle = generatePuzzle({
      difficulty: level,
      seed: `CAL-${bucket.id}-${collected.length}-${level}`,
      islands,
      format: useBooklet ? BOOKLET_FORMAT : cfg,
      keep: 1,
    });
    const board = buildBoard(
      puzzle.islands.map((i) => ({ id: i.id, r: i.r, c: i.c, num: i.num })),
      puzzle.cols,
      puzzle.rows,
    );
    const solver = new Solver(board);
    solver.findSolutions(2);
    collected.push(measure(board, solver, solver.ruleSteps));
    if (collected.length % 20 === 0) {
      process.stdout.write(`\r  ${bucket.id}: ${collected.length}/${SAMPLES} `);
    }
  }
  samples.set(bucket.id, collected);
  process.stdout.write(`\r  ${bucket.id}: ${SAMPLES}/${SAMPLES} ✓\n`);
}

const calibration = {};
for (const [id, rows] of samples) {
  calibration[id] = {};
  for (const metric of METRICS) {
    const values = rows.map((r) => r[metric]).sort((a, b) => a - b);
    calibration[id][metric] = [
      Number(percentile(values, 0.05).toFixed(4)),
      Number(percentile(values, 0.95).toFixed(4)),
    ];
  }
  // Übersicht
  const nodes = rows.map((r) => r.nodes).sort((a, b) => a - b);
  const logic = rows.map((r) => r.logicShare).sort((a, b) => a - b);
  console.log(
    `  ${id.padEnd(8)} Knoten median=${percentile(nodes, 0.5).toFixed(0)} ` +
    `Logikanteil median=${(percentile(logic, 0.5) * 100).toFixed(0)}%`,
  );
}

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, `${JSON.stringify(calibration, null, 2)}\n`);
console.log(`\nKalibrierung geschrieben: ${OUT}`);

