// Vorab-Validierung: trennt die globale Normierung die Stufen?
import { CALIBRATION } from "./js/data/difficulty.js";
import { generatePuzzle } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { Solver } from "./js/solver.js";
import { measure, METRICS } from "./js/difficulty.js";

// Globale Referenz aus allen Bündeln bilden
const global = {};
for (const metric of METRICS) {
  const los = [];
  for (const entry of Object.values(CALIBRATION)) {
    if (!entry[metric]) continue;
    los.push(entry[metric][0], entry[metric][1]);
  }
  global[metric] = [Math.min(...los), Math.max(...los)];
}
console.log("globale Referenz:", JSON.stringify(global));

const W = { nodes: 0.4, logicShare: 0.3, avgNumber: 0.2, density: 0.1 };
const norm = (v, [lo, hi]) => (hi === lo ? 0 : Math.max(0, Math.min(1, (v - lo) / (hi - lo))));

function scoreOf(m) {
  let s = 0;
  for (const metric of METRICS) {
    let v = norm(m[metric], global[metric]);
    if (metric === "logicShare") v = 1 - v;
    s += v * W[metric];
  }
  return s;
}

console.log("\nStufe     n    score-Werte                       avg");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  const vals = [];
  for (let i = 0; i < 8; i++) {
    const p = generatePuzzle({ difficulty: diff, seed: `VALID-${diff}-${i}` });
    const b = buildBoard(
      p.islands.map((x) => ({ id: x.id, r: x.r, c: x.c, num: x.num })),
      p.cols, p.rows,
    );
    const s = new Solver(b);
    s.findSolutions(2);
    vals.push(scoreOf(measure(b, s, s.ruleSteps)));
  }
  const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
  console.log(
    `${diff.padEnd(8)} ${String(p.islands.length).padStart(3)}  ` +
    `${vals.map((v) => v.toFixed(2)).join(" ")}  ${avg.toFixed(3)}`,
  );
}

