// Vergleich: metrikbasierter Ansatz (fremdes Projekt) gegen die
// Struktur-Heuristik dieses Projekts.
import { generatePuzzle } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { Solver } from "./js/solver.js";

/** Die "qualityScore" des Projekts – reine Struktur-Heuristik. */
function qualityScore(board, counts) {
  let score = 0;
  const nums = board.islands.map((i) => i.num);
  const doubles = counts.filter((c) => c === 2).length;
  score += board.islands.length * 0.6;
  score += 2.0 * nums.filter((n) => n >= 3).length;
  score += 1.5 * nums.filter((n) => n >= 5).length;
  score += 1.6 * doubles;
  score += 1.2 * new Set(nums).size;
  score -= 0.5 * nums.filter((n) => n === 1).length;
  return score;
}

const rows = [];
for (const diff of ["easy", "medium", "hard", "expert"]) {
  for (let i = 0; i < 6; i++) {
    const p = generatePuzzle({ difficulty: diff, seed: `VERGLEICH-${diff}-${i}` });
    const b = buildBoard(
      p.islands.map((x) => ({ id: x.id, r: x.r, c: x.c, num: x.num })),
      p.cols, p.rows,
    );
    const s = new Solver(b);
    s.findSolutions(2);
    rows.push({
      diff,
      inseln: p.islands.length,
      knoten: s.nodes,
      qual: qualityScore(b, p.solution),
    });
  }
}

console.log("Stufe     n    Solver-Knoten  Struktur-Qualität");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  const sub = rows.filter((r) => r.diff === diff);
  const avg = (k) => (sub.reduce((s, r) => s + r[k], 0) / sub.length).toFixed(1);
  console.log(
    `${diff.padEnd(8)} ${avg("inseln").padStart(3)}  ${avg("knoten").padStart(12)}  ${avg("qual").padStart(16)}`,
  );
}

// Korrelationen
function korrektur(xs, ys) {
  const n = xs.length;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let num = 0, dx = 0, dy = 0;
  for (let i = 0; i < n; i++) {
    num += (xs[i] - mx) * (ys[i] - my);
    dx += (xs[i] - mx) ** 2;
    dy += (ys[i] - my) ** 2;
  }
  return num / Math.sqrt(dx * dy);
}
const n = rows.map((r) => r.inseln);
console.log(`\nKorrelation Inselzahl <-> Solver-Knoten:    r = ${korrektur(n, rows.map((r) => r.knoten)).toFixed(3)}`);
console.log(`Korrelation Inselzahl <-> Struktur-Qualität: r = ${korrektur(n, rows.map((r) => r.qual)).toFixed(3)}`);
console.log(`Korrelation Solver-Knoten <-> Struktur-Qualität: r = ${korrektur(rows.map((r) => r.knoten), rows.map((r) => r.qual)).toFixed(3)}`);

