const tabID = (await tools.browser.tabs.list()).tabs.find(x => x.url.includes("TOUCH")).id;
const r = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const gen = await import('./js/generator.js');
    const brd = await import('./js/board.js');
    const canvas = document.getElementById('board');
    const rect = canvas.getBoundingClientRect();
    const seed = document.getElementById('seedInput').value;
    const p = gen.generatePuzzle({ difficulty: 'medium', seed });
    const board = brd.buildBoard(p.islands, p.cols, p.rows);
    const margin = Math.max(10, Math.min(rect.width, rect.height) * 0.05);
    const cell = Math.min((rect.width - 2*margin) / p.cols, (rect.height - 2*margin) / p.rows);
    const ox = rect.left + (rect.width - cell*p.cols)/2, oy = rect.top + (rect.height - cell*p.rows)/2;
    const ctr = (r0,c0) => ({ x: ox + (c0+0.5)*cell, y: oy + (r0+0.5)*cell });

    // Touch-Pointer: down -> move -> up (wie beim Ziehen auf dem Handy)
    const fire = (type, x, y) => canvas.dispatchEvent(new PointerEvent(type, {
      clientX: x, clientY: y, bubbles: true, cancelable: true,
      pointerId: 7, isPrimary: true, pointerType: 'touch',
    }));

    const e = board.edges[0];
    const A = ctr(p.islands[e.a].r, p.islands[e.a].c);
    const B = ctr(p.islands[e.b].r, p.islands[e.b].c);
    const mid = { x: (A.x+B.x)/2, y: (A.y+B.y)/2 };

    fire('pointerdown', mid.x, mid.y);
    fire('pointerup', mid.x, mid.y);
    const nachTippen = document.getElementById('bridgeCount').textContent;

    // Ziehen von Insel zu Insel
    const e2 = board.edges.find(x => x.id !== e.id);
    const C = ctr(p.islands[e2.a].r, p.islands[e2.a].c);
    const D = ctr(p.islands[e2.b].r, p.islands[e2.b].c);
    fire('pointerdown', C.x, C.y);
    fire('pointermove', (C.x+D.x)/2, (C.y+D.y)/2);
    fire('pointermove', D.x, D.y);
    fire('pointerup', D.x, D.y);
    const nachZiehen = document.getElementById('bridgeCount').textContent;

    return { nachTippen, nachZiehen, status: document.getElementById('status').textContent };
  })()`
});
const cons = await tools.browser.console({ tabID, level: "error", limit: 10 });
return { r: r.value, errors: cons.messages };

