    const margin = Math.max(10, Math.min(rect.width, rect.height) * 0.05);
    const cell = Math.min((rect.width - 2*margin) / p.cols, (rect.height - 2*margin) / p.rows);
    const ox = rect.left + (rect.width - cell*p.cols)/2, oy = rect.top + (rect.height - cell*p.rows)/2;
    const ctr = (r0,c0) => ({ x: ox + (c0+0.5)*cell, y: oy + (r0+0.5)*cell });
    const fire = (type, x, y) => canvas.dispatchEvent(new PointerEvent(type, {
      clientX: x, clientY: y, bubbles: true, cancelable: true,
      pointerId: 7, isPrimary: true, pointerType: 'touch',
    }));

