          r: nr,
          c: nc,
          w,
          // Abstand zur nächstgelegenen anderen Insel: je grösser, desto
          // gleichmässiger verteilen sich die Inseln.
          abstand: nearestDistance(islands, nr, nc, i),
        });
      }
    }
