// Misst die Gleichmässigkeit der Inselverteilung und die Eindeutigkeitsquote.
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions } from "./js/solver.js";

/** Mittlerer Abstand jeder Insel zur nächstgelegenen anderen Insel. */
function nearestAvg(islands) {
  let sum = 0;
  for (let i = 0; i < islands.length; i++) {
    let best = Infinity;
    for (let j = 0; j < islands.length; j++) {
      if (i === j) continue;
      const d = Math.abs(islands[i].r - islands[j].r) + Math.abs(islands[i].c - islands[j].c);
      if (d < best) best = d;
    }
    sum += best;
  }
  return sum / islands.length;
}

/** Zählt Paare von Inseln, die direkt nebeneinander liegen. */
function adjacentPairs(islands) {
  let n = 0;
  for (let i = 0; i < islands.length; i++) {
    for (let j = i + 1; j < islands.length; j++) {
      const d = Math.abs(islands[i].r - islands[j].r) + Math.abs(islands[i].c - islands[j].c);
      if (d === 1) n++;
    }
  }
  return n;
}

console.log("Variante          ziel  erreicht  quote  versuche  abstand  nebenbei");
for (const [label, noAdj, extra, cols, rows, target] of [
  ["ohne Regel", false, 2, 12, 12, 40],
  ["mit Regel", true, 2, 12, 12, 40],
  ["mit Regel, 60", true, 2, 16, 14, 60],
  ["mit Regel, 100", true, 2, 22, 20, 100],
]) {
  let quote = 0, versuche = 0, erreicht = 0, abstand = 0, neben = 0, tSum = 0;
  const N = 5;
  for (let i = 0; i < N; i++) {
    const rng = new RNG(`GLEICH|${label}|${i}`);
    const t0 = Date.now();
    for (let v = 0; v < 30; v++) {
      versuche++;
      const sol = internals.growSolution(rng, target, cols, rows, 0.12, extra, 4, noAdj);
      if (!sol) continue;
      if (sol.islands.length >= target) erreicht++;
      if (!internals.validateSolution(sol)) continue;
      const b = internals.boardOf(sol, internals.numbersOf(sol));
      if (findSolutions(b, 2).length === 1) {
        quote++;
        abstand += nearestAvg(sol.islands);
        neben += adjacentPairs(sol.islands);
        break;
      }
    }
    tSum += Date.now() - t0;
  }
  const n = Math.max(1, quote);
  console.log(
    `${label.padEnd(16)} ${String(target).padStart(4)}  ${(erreicht / N).toFixed(1).padStart(8)}  ` +
    `${((quote / N) * 100).toFixed(0).padStart(4)}%  ${(versuche / n).toFixed(1).padStart(7)}  ` +
    `${(abstand / n).toFixed(2).padStart(8)}  ${(neben / n).toFixed(1).padStart(8)}  ${(tSum / N).toFixed(0)}ms`,
  );
}

// Wie viele Inseln sind mit der Nachbar-Regel je Raster überhaupt möglich?
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";

console.log("Raster    erreichte Inseln (5 Versuche)      min  avg  max");
for (const [cols, rows] of [[12, 12], [14, 14], [16, 16], [18, 16], [20, 18], [22, 20], [24, 22]]) {
  const vals = [];
  for (let i = 0; i < 5; i++) {
    const rng = new RNG("REICH|${cols}|${rows}|" + i);
    const sol = internals.growSolution(rng, 999, cols, rows, 0.12, 2, 4, true);
    vals.push(sol ? sol.islands.length : 0);
  }
  const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
  console.log(
    `${String(cols + 'x' + rows).padEnd(9)} ${vals.map((v) => String(v).padStart(4)).join("")}` +
    `   ${String(Math.min(...vals)).padStart(4)} ${avg.toFixed(1).padStart(5)} ${String(Math.max(...vals)).padStart(4)}`,
  );
}

// End-to-End-Benchmark mit der Nachbar-Regel und gleichmässiger Verteilung
import { generatePuzzle, BOOKLET_FORMAT } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { findSolutions } from "./js/solver.js";

function adjacentPairs(islands) {
  let n = 0;
  for (let i = 0; i < islands.length; i++) {
    for (let j = i + 1; j < islands.length; j++) {
      if (Math.abs(islands[i].r - islands[j].r) + Math.abs(islands[i].c - islands[j].c) === 1) n++;
    }
  }
  return n;
}
function nearestAvg(islands) {
  let sum = 0;
  for (let i = 0; i < islands.length; i++) {
    let best = Infinity;
    for (let j = 0; j < islands.length; j++) {
      if (i === j) continue;
      const d = Math.abs(islands[i].r - islands[j].r) + Math.abs(islands[i].c - islands[j].c);
      if (d < best) best = d;
    }
    sum += best;
  }
  return sum / islands.length;
}

console.log("Stufe     ok   inseln  doppel  abstand  nebenbei  zeit avg   max");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  let ok = 0, tSum = 0, tMax = 0, nSum = 0, dSum = 0, ab = 0, nb = 0;
  const N = 12;
  for (let i = 0; i < N; i++) {
    const t0 = Date.now();
    const p = generatePuzzle({ difficulty: diff, seed: `LUFT-${diff}-${i}` });
    const dt = Date.now() - t0;
    tSum += dt; tMax = Math.max(tMax, dt);
    const b = buildBoard(p.islands, p.cols, p.rows);
    const s = findSolutions(b, 2);
    if (s.length === 1 && JSON.stringify(s[0]) === JSON.stringify(p.solution)) ok++;
    nSum += p.islands.length; dSum += p.doubles;
    ab += nearestAvg(p.islands); nb += adjacentPairs(p.islands);
  }
  console.log(
    `${diff.padEnd(8)} ${ok}/${N} ${(nSum / N).toFixed(0).padStart(5)}  ${(dSum / N).toFixed(1).padStart(5)}  ` +
    `${(ab / N).toFixed(2).padStart(7)}  ${(nb / N).toFixed(1).padStart(8)}  ${(tSum / N).toFixed(0).padStart(7)}ms ${String(tMax).padStart(6)}ms`,
  );
}

let ok = 0, tSum = 0, tMax = 0, ab = 0, nb = 0, dSum = 0;
const N = 6;
for (let i = 0; i < N; i++) {
  const t0 = Date.now();
  const p = generatePuzzle({ difficulty: "medium", seed: `HEFTL-${i}`, islands: 100, format: BOOKLET_FORMAT, keep: 1 });
  const dt = Date.now() - t0; tSum += dt; tMax = Math.max(tMax, dt);
  const b = buildBoard(p.islands, p.cols, p.rows);
  if (findSolutions(b, 2).length === 1) ok++;
  ab += nearestAvg(p.islands); nb += adjacentPairs(p.islands); dSum += p.doubles;
