// Diagnose: Hat die Stufen-Wahl im Rätselheft überhaupt einen Effekt?
import { generatePuzzle, BOOKLET_FORMAT } from "./js/generator.js";
import { buildBoard } from "./js/board.js";
import { findSolutions } from "./js/solver.js";

console.log("Stufe     Inseln  Raster   gemessene Schwierigkeit   Knoten  logisch");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  for (const n of [40, 100]) {
    const p = generatePuzzle({
      difficulty: diff,
      seed: `DIAG-${diff}-${n}`,
      islands: n,
      format: BOOKLET_FORMAT,
      keep: 1,
    });
    const b = buildBoard(p.islands, p.cols, p.rows);
    const s = findSolutions(b, 2);
    const { propagationStatus } = await import("./js/solver.js");
    const st = propagationStatus(b);
    console.log(
      `${diff.padEnd(9)} ${String(p.islands.length).padStart(5)}  ${(p.cols + "x" + p.rows).padEnd(7)} ` +
      `${p.difficultyScore.toFixed(3).padStart(14)} (${p.difficultyText.padEnd(12)}) ` +
      `${String(s.length).padStart(6)}  ${((st.determined / b.edges.length) * 100).toFixed(0).padStart(6)}%`,
    );
  }
}

// Kernfrage: Kann ein Rätsel mit 100 Inseln leicht sein?
// Untersucht wird, welcher Stellschraube die Schwierigkeit steuert.
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions, propagationStatus, Solver } from "./js/solver.js";
import { measure, score } from "./js/difficulty.js";
import { CALIBRATION } from "./js/data/difficulty.js";
import { bucketFor } from "./js/difficulty.js";

const N = 100;

console.log(`Rätsel mit ${N} Inseln – Verteilung der gemessenen Schwierigkeit`);
console.log("maxExtra  quote  min    Ø      max    logisch(Median)  Knoten(Median)");

for (const maxExtra of [0, 1, 2, 3]) {
  const werte = [];
  let quote = 0, versuche = 0, logic = [], nodes = [];
  const R = 10;
  for (let i = 0; i < R; i++) {
    const rng = new RNG(`HART|${maxExtra}|${i}`);
    for (let v = 0; v < 25; v++) {
      versuche++;
      const sol = internals.growSolution(rng, N, 23, 21, 0.12, maxExtra, 4, true);
      if (!sol || sol.islands.length < N) continue;
      if (!internals.validateSolution(sol)) continue;
      const b = internals.boardOf(sol, internals.numbersOf(sol));
      const sv = new Solver(b);
      if (sv.findSolutions(2).length !== 1) continue;
      quote++;
      const st = propagationStatus(b);
      logic.push(st.determined / b.edges.length);
      nodes.push(sv.nodes);
      werte.push(score(measure(b, sv, sv.ruleSteps), CALIBRATION.global));
      break;
    }
  }
  if (!werte.length) {
    console.log(`${String(maxExtra).padEnd(9)} ${quote}/${R}   (keine eindeutigen Rätsel gefunden)`);
    continue;
  }
  werte.sort((a, b) => a - b);
  logic.sort((a, b) => a - b);
  nodes.sort((a, b) => a - b);
  const med = (a) => a[Math.floor(a.length / 2)];
  console.log(
    `${String(maxExtra).padEnd(9)} ${String(quote).padStart(2)}/${R}   ` +
    `${werte[0].toFixed(3)}  ${med(werte).toFixed(3)}  ${werte[werte.length - 1].toFixed(3)}  ` +
    `${(med(logic) * 100).toFixed(0).padStart(13)}%  ${String(med(nodes)).padStart(13)}`,
  );
}

// Kann ein 100-Inseln-Rätsel leicht sein? Test: Rastergrösse und
// Brückenlängen als Stellschrauben.
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { findSolutions, propagationStatus, Solver } from "./js/solver.js";
import { measure, score, bucketFor } from "./js/difficulty.js";
import { CALIBRATION } from "./js/data/difficulty.js";

const N = 100;

console.log(`100 Inseln: Rastergrösse x maxExtra -> Schwierigkeit / Logikanteil / Quote`);
for (const [cols, rows] of [[23, 21], [28, 26], [34, 32], [42, 40]]) {
  for (const maxExtra of [1, 2]) {
    const werte = [];
    let quote = 0, logic = [], reached = 0;
    const R = 6;
    for (let i = 0; i < R; i++) {
      const rng = new RNG(`GROSS|${cols}|${maxExtra}|${i}`);
      for (let v = 0; v < 20; v++) {
        const sol = internals.growSolution(rng, N, cols, rows, 0.12, maxExtra, 4, true);
        if (!sol || sol.islands.length < N) continue;
        reached++;
        if (!internals.validateSolution(sol)) continue;
        const b = internals.boardOf(sol, internals.numbersOf(sol));
        const sv = new Solver(b);
        if (sv.findSolutions(2).length !== 1) continue;
        quote++;
        const st = propagationStatus(b);
        logic.push(st.determined / b.edges.length);
        werte.push(score(measure(b, sv, sv.ruleSteps), CALIBRATION.global));
        break;
      }
    }
    if (!werte.length) {
      console.log(`${(cols + "x" + rows).padEnd(8)} extra=${maxExtra}: Ziel nicht erreicht (${reached}/${R})`);
      continue;
    }
    werte.sort((a, b) => a - b);
    logic.sort((a, b) => a - b);
    const med = (a) => a[Math.floor(a.length / 2)];
    console.log(
      `${(cols + "x" + rows).padEnd(8)} extra=${maxExtra}: ` +
      `Schwierigkeit min=${werte[0].toFixed(2)} Ø=${med(werte).toFixed(2)} max=${werte[werte.length-1].toFixed(2)}  ` +
      `Logik ${(med(logic) * 100).toFixed(0)}%  Quote ${quote}/${R}`,
    );
  }
}

