// Kerntest: Erzeugt der Generator Rätsel im gewünschten Schwierigkeitsband?
import { generatePuzzle, BOOKLET_FORMAT } from "./js/generator.js";
import { LEVEL_BANDS } from "./js/difficulty.js";
import { buildBoard } from "./js/board.js";
import { findSolutions } from "./js/solver.js";

console.log("Ziel     Inseln  Raster   gemessen      im Band  Knoten  Zeit");
for (const level of ["easy", "medium", "hard", "expert"]) {
  for (const n of [40, 100]) {
    const band = LEVEL_BANDS[level];
    let treffer = 0, sum = 0, tSum = 0, tMax = 0;
    let raster = "";
    const N = 5;
    for (let i = 0; i < N; i++) {
      const t0 = Date.now();
      const p = generatePuzzle({
        difficulty: level,
        seed: `BAND-${level}-${n}-${i}`,
        islands: n,
        format: BOOKLET_FORMAT,
        keep: 1,
        target: level,
      });
      const dt = Date.now() - t0;
      tSum += dt; tMax = Math.max(tMax, dt);
      const b = buildBoard(p.islands, p.cols, p.rows);
      if (findSolutions(b, 2).length === 1) {
        sum += p.difficultyScore;
        if (p.difficultyScore >= band[0] && p.difficultyScore <= band[1]) treffer++;
      }
      raster = `${p.cols}x${p.rows}`;
    }
    console.log(
      `${level.padEnd(8)} ${String(n).padStart(6)}  ${raster.padEnd(8)} ` +
      `Ø ${(sum / N).toFixed(3)}      ${treffer}/${N}      ${String(tMax).padStart(5)}ms  ` +
      `${(tSum / N).toFixed(0)}ms`,
    );
  }
}

