// Wie viele Inseln sind je Parameterkombination bei einer Stufe möglich?
// Gesucht wird die GRÖSSTE Inselzahl, die den Schwierigkeitsgrad noch hält.
import { RNG } from "./js/rng.js";
import { internals } from "./js/generator.js";
import { Solver, propagationStatus } from "./js/solver.js";
import { measure, score, LEVEL_BANDS } from "./js/difficulty.js";
import { CALIBRATION } from "./js/data/difficulty.js";

const COUNTS = [20, 30, 40, 50, 60, 70, 85];
const BAND = LEVEL_BANDS.easy; // "leicht" als strengste Stufe

function attempt(rng, islands, cols, rows, maxExtra, double, maxLen) {
  const sol = internals.growSolution(rng, islands, cols, rows, double, maxExtra, maxLen, true);
  if (!sol || sol.islands.length < islands) return null;
  if (!internals.validateSolution(sol)) return null;
  const b = internals.boardOf(sol, internals.numbersOf(sol));
  const sv = new Solver(b);
  if (sv.findSolutions(2).length !== 1) return null;
  return score(measure(b, sv, sv.ruleSteps), CALIBRATION.global);
}

console.log(`Zielband „leicht": ${BAND[0].toFixed(2)}–${BAND[1].toFixed(2)}`);
console.log("maxExtra  doppelt  maxLen  erreichte Inselzahl (je 5 Versuchen)");
for (const maxExtra of [1, 2, 3]) {
  for (const double of [0, 0.08, 0.2]) {
    for (const maxLen of [3, 4, 6]) {
      let best = 0;
      for (const islands of COUNTS) {
        let ok = 0;
        for (let i = 0; i < 5; i++) {
          const rng = new RNG(`OPT|${maxExtra}|${double}|${maxLen}|${islands}|${i}`);
          // Raster so weit, wie es die Inselzahl erlaubt
          const side = Math.max(islands + 6, Math.round(Math.sqrt(islands * 9)));
          const v = attempt(rng, islands, side, side, maxExtra, double, maxLen);
          if (v !== null && v >= BAND[0] && v <= BAND[1]) ok++;
        }
        if (ok === 0) break;
        best = islands;
      }
      console.log(
        `${String(maxExtra).padEnd(9)} ${String(double).padEnd(8)} ${String(maxLen).padEnd(7)} ${best}`,
      );
    }
  }
}

