input.content:
// Trifft die gewählte Inselzahl die Schwierigkeitsstufe?
import { generatePuzzle, DIFFICULTIES, BOOKLET_FORMAT } from "./js/generator.js";
import { LEVEL_BANDS } from "./js/difficulty.js";
import { buildBoard } from "./js/board.js";
import { findSolutions } from "./js/solver.js";

console.log("Stufe     Inseln  Raster   gemessen      im Band  Zeit");
for (const diff of ["easy", "medium", "hard", "expert"]) {
  const band = LEVEL_BANDS[diff];
  for (const n of [16, 22, 30, 40, 50, 65]) {
    const t0 = Date.now();
    const p = generatePuzzle({
      difficulty: diff,
      seed: `STUFE-${diff}-${n}`,
      islands: n,
      format: { ...BOOKLET_FORMAT, cols: DIFFICULTIES[diff].cols, rows: DIFFICULTIES[diff].rows },
      keep: 1,
      target: diff,
    });
    const dt = Date.now() - t0;
    const b = buildBoard(p.islands, p.cols, p.rows);
    const ok = findSolutions(b, 2).length === 1;
    const drin = p.difficultyScore >= band[0] && p.difficultyScore <= band[1];
    console.log(
      `${diff.padEnd(8)} ${String(n).padStart(6)}  ${(p.cols + "x" + p.rows).padEnd(8)} ` +
      `${p.difficultyScore.toFixed(3).padStart(7)}      ${(drin ? "ja" : "NEIN").padStart(5)}  ` +
      `${dt}ms  eindeutig=${ok ? "ja" : "NEIN"}`,
    );
  }
}

